// ============================================================
//  Test学号日期.cpp  —— 函数模板 + 集合类模板 完整实现
// ============================================================

#include <iostream>
#include <string>
#include <cstdlib>   // rand / srand
using namespace std;

// ============================================================
//  自定义复数类 complex1
// ============================================================
class complex1 {
    double real, imag;
public:
    complex1(double r = 0, double i = 0) : real(r), imag(i) {}

    bool operator==(const complex1 &o) const {
        return real == o.real && imag == o.imag;
    }

    friend ostream &operator<<(ostream &out, const complex1 &c) {
        out << c.real;
        if (c.imag >= 0) out << "+" << c.imag << "i";
        else             out << c.imag << "i";
        return out;
    }
};

// ============================================================
//  函数模板定义区
// ============================================================

// 1. 求数组最大值和最小值
template <typename T>
void MaxMinofArray(T arr[], int n, T &maxVal, T &minVal) {
    maxVal = minVal = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > maxVal) maxVal = arr[i];
        if (arr[i] < minVal) minVal = arr[i];
    }
}

// 2. 打印数组全部元素
template <typename T>
void ArrayPrint(T arr[], int n) {
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;
}

// 3. 从数组中查找并删除指定元素，返回删除数量
//    (原地删除：将非目标元素向前紧缩，n 通过引用更新)
template <typename T>
int DeleteElm(T arr[], int &n, const T &val) {
    int count = 0, newSize = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] == val) {
            count++;
        } else {
            arr[newSize++] = arr[i];
        }
    }
    n = newSize;
    return count;
}

// ============================================================
//  集合类模板  Set<T, size>
//  (放在独立头文件时把下面内容移至 学号Settemplate.h)
// ============================================================
template <typename T, int size>
class Set {
    T   elements[size];
    int num;
public:
    // 构造函数
    Set() : num(0) {}

    // 复制构造函数
    Set(const Set &s) {
        num = s.num;
        for (int i = 0; i < num; i++) elements[i] = s.elements[i];
    }

    // 向集合添加元素（不重复），溢出返回 false
    bool AddElem(T e) {
        if (num >= size) return false;
        if (IsMember(e))  return false;   // 集合元素唯一
        elements[num++] = e;
        return true;
    }

    // 判断是否是成员
    bool IsMember(T e) const {
        for (int i = 0; i < num; i++)
            if (elements[i] == e) return true;
        return false;
    }

    // 删除一个元素
    void RemoveElem(T e) {
        for (int i = 0; i < num; i++) {
            if (elements[i] == e) {
                for (int j = i; j < num - 1; j++)
                    elements[j] = elements[j + 1];
                num--;
                return;
            }
        }
    }

    // 将另一集合的所有元素复制到本集合（覆盖）
    void Copy(const Set &s) {
        num = s.num;
        for (int i = 0; i < num; i++) elements[i] = s.elements[i];
    }

    // 判断两集合是否完全相同
    bool IsEqual(const Set &s) const {
        if (num != s.num) return false;
        for (int i = 0; i < num; i++)
            if (!s.IsMember(elements[i])) return false;
        return true;
    }

    // 求交集
    Set Intersect(const Set &s) const {
        Set result;
        for (int i = 0; i < num; i++)
            if (s.IsMember(elements[i]))
                result.AddElem(elements[i]);
        return result;
    }

    // 求并集（溢出时返回尽量大的集合）
    Set Unionset(const Set &s) const {
        Set result(*this);
        for (int i = 0; i < s.num; i++)
            result.AddElem(s.elements[i]);
        return result;
    }

    // 判断参数集合是否包含于本集合内
    bool IsContain(const Set &s) const {
        for (int i = 0; i < s.num; i++)
            if (!IsMember(s.elements[i])) return false;
        return true;
    }

    // 友元输出运算符
    template <typename U, int sz>
    friend ostream &operator<<(ostream &out, const Set<U, sz> &s);
};

template <typename T, int size>
ostream &operator<<(ostream &out, const Set<T, size> &s) {
    for (int i = 0; i < s.num; i++)
        out << s.elements[i] << " ";
    out << endl;
    return out;
}

// ============================================================
//  函数模板测试函数
// ============================================================
void templatetest() {
    cout << "函数模板测试\n-------------\n";

    double d1[7] = {8.1, 2.2, 3.9, 9.3, 5.4, 6.5, 7.8};
    int    a1[]  = {101, 204, 300, 18, 57, 77, 99, 23, 18};
    char   c1[]  = "Program of template";
    string s1[6] = {"cat", "dog", "fox", "ox", "hen", "lion"};

    // --- double ---
    double dmax, dmin;
    cout << "double 数组: ";
    ArrayPrint(d1, 7);
    MaxMinofArray(d1, 7, dmax, dmin);
    cout << "最大值为" << dmax << "\t最小值为" << dmin << endl;
    cout << endl;

    // --- int ---
    int imax, imin;
    int na1 = 9;
    cout << "int 数组: ";
    ArrayPrint(a1, na1);
    MaxMinofArray(a1, na1, imax, imin);
    cout << "最大值为" << imax << "\t最小值为" << imin << endl;
    int N = DeleteElm(a1, na1, 18);
    cout << "删除元素 18，共删除 " << N << " 个，删除后数组: ";
    ArrayPrint(a1, na1);
    cout << endl;

    // --- char ---
    char cmax, cmin;
    int nc1 = (int)strlen(c1);   // 不含 '\0'
    cout << "char 数组: ";
    ArrayPrint(c1, nc1);
    MaxMinofArray(c1, nc1, cmax, cmin);
    cout << "最大值为" << cmax << "\t最小值为" << cmin << endl;
    int Nc = DeleteElm(c1, nc1, (char)'e');
    c1[nc1] = '\0';  // 保持 C 串合法
