//  (放在独立头文件时把下面内容移至 学号Settemplate.h)
// ============================================================
template <typename T, int size>
class Set {
    T   elements[size];
    int num;
public:
    // 构造函数
    Set() : num(0) {}

    // 复制构造函数
    Set(const Set &s) {
        num = s.num;
        for (int i = 0; i < num; i++) elements[i] = s.elements[i];
    }

    // 向集合添加元素（不重复），溢出返回 false
    bool AddElem(T e) {
        if (num >= size) return false;
        if (IsMember(e))  return false;   // 集合元素唯一
        elements[num++] = e;
        return true;
    }

    // 判断是否是成员
    bool IsMember(T e) const {
        for (int i = 0; i < num; i++)
            if (elements[i] == e) return true;
        return false;
    }

    // 删除一个元素
    void RemoveElem(T e) {
        for (int i = 0; i < num; i++) {
            if (elements[i] == e) {
                for (int j = i; j < num - 1; j++)
                    elements[j] = elements[j + 1];
                num--;
                return;
            }
        }
    }

    // 将另一集合的所有元素复制到本集合（覆盖）
    void Copy(const Set &s) {
        num = s.num;
        for (int i = 0; i < num; i++) elements[i] = s.elements[i];
    }

    // 判断两集合是否完全相同
    bool IsEqual(const Set &s) const {
        if (num != s.num) return false;
        for (int i = 0; i < num; i++)
            if (!s.IsMember(elements[i])) return false;
        return true;
    }

    // 求交集
    Set Intersect(const Set &s) const {
        Set result;
        for (int i = 0; i < num; i++)
            if (s.IsMember(elements[i]))
                result.AddElem(elements[i]);
        return result;
    }

    // 求并集（溢出时返回尽量大的集合）
    Set Unionset(const Set &s) const {
        Set result(*this);
        for (int i = 0; i < s.num; i++)
            result.AddElem(s.elements[i]);
        return result;
    }

    // 判断参数集合是否包含于本集合内
    bool IsContain(const Set &s) const {
        for (int i = 0; i < s.num; i++)
            if (!IsMember(s.elements[i])) return false;
        return true;
    }

    // 友元输出运算符
    template <typename U, int sz>
    friend ostream &operator<<(ostream &out, const Set<U, sz> &s);
};

