// ============================================================
// MyFraction class  (1/denominator, compared by value)
// ============================================================
class MyFraction {
    int numerator;
    int denominator;
public:
    MyFraction() : numerator(1), denominator(1) {}
    MyFraction(int n, int d) : numerator(n), denominator(d) {}

    // Compare by value: a/b vs c/d  ->  a*d vs c*b
    bool operator==(const MyFraction& o) const {
        return numerator * o.denominator == o.numerator * denominator;
    }
    bool operator<(const MyFraction& o) const {
        return numerator * o.denominator < o.numerator * denominator;
    }
    bool operator>(const MyFraction& o) const {
        return numerator * o.denominator > o.numerator * denominator;
    }

    friend ostream& operator<<(ostream& out, const MyFraction& f) {
        out << f.numerator << "/" << f.denominator;
        return out;
    }
};

