using namespace std;

// ============================================================
// seqlist class template
// ============================================================
template <typename T, int size>
class seqlist {
    T slate[size];
    int Maxsize;
    int last;
public:
    seqlist() { last = -1; Maxsize = size; }
    int Length() const { return last + 1; }

    int Find(const T& x) const {
        for (int i = 0; i <= last; i++)
            if (slate[i] == x) return i;
        return -1;
    }

    bool IsIn(const T& x) const { return Find(x) != -1; }

    bool Insert(const T& x, int i) {
        if (last == Maxsize - 1 || i < 0 || i > last + 1) return false;
        for (int j = last; j >= i; j--)
            slate[j + 1] = slate[j];
        slate[i] = x;
        last++;
        return true;
    }

    bool Remove(const T& x) {
        int pos = Find(x);
        if (pos == -1) return false;
        for (int i = pos; i < last; i++)
            slate[i] = slate[i + 1];
        last--;
        return true;
    }

    int Next(const T& x) const {
        int pos = Find(x);
        if (pos == -1 || pos == last) return -1;
        return pos + 1;
    }

    int Prior(const T& x) const {
        int pos = Find(x);
        if (pos <= 0) return -1;
        return pos - 1;
    }

    bool isEmpty() { return last == -1; }
    bool IsFull() { return last == Maxsize - 1; }

    T& operator[](int i) { return slate[i]; }

    void clear() { last = -1; }

    // ---- 6 new member functions ----

    // 1) Reverse in place
    void Reverse() {
        int lo = 0, hi = last;
        while (lo < hi) {
            T tmp = slate[lo];
            slate[lo] = slate[hi];
            slate[hi] = tmp;
            lo++; hi--;
        }
    }

    // 2) Descending direct insertion sort
    void DownInsertSort() {
        for (int i = 1; i <= last; i++) {
            T tmp = slate[i];
            int j = i - 1;
            while (j >= 0 && slate[j] < tmp) {
                slate[j + 1] = slate[j];
                j--;
            }
            slate[j + 1] = tmp;
        }
    }

    // 3) Descending binary insertion sort
    void DownBinaryInsertSort() {
        for (int i = 1; i <= last; i++) {
            T tmp = slate[i];
            int lo = 0, hi = i - 1;
            // Find insertion position: first pos where slate[pos] < tmp
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (slate[mid] < tmp) hi = mid - 1;
                else lo = mid + 1;
            }
            for (int j = i - 1; j >= lo; j--)
                slate[j + 1] = slate[j];
            slate[lo] = tmp;
        }
    }

    // 4) Descending bubble sort
    void DownBubbleSort() {
        for (int i = 0; i < last; i++) {
            bool swapped = false;
            for (int j = last; j > i; j--) {
                if (slate[j] > slate[j - 1]) {
                    T tmp = slate[j];
                    slate[j] = slate[j - 1];
                    slate[j - 1] = tmp;
                    swapped = true;
                }
            }
            if (!swapped) break;
        }
    }

    // 5) Descending selection sort
    void DownSelectSort() {
        for (int i = 0; i <= last; i++) {
            int maxIdx = i;
            for (int j = i + 1; j <= last; j++)
                if (slate[j] > slate[maxIdx]) maxIdx = j;
            if (maxIdx != i) {
                T tmp = slate[i];
                slate[i] = slate[maxIdx];
                slate[maxIdx] = tmp;
            }
        }
    }

    // 6) Binary search on descending-sorted list
    int DownBinarySearch(const T& x) const {
        int lo = 0, hi = last;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (slate[mid] == x) return mid;
            else if (slate[mid] > x) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }

    template<typename U, int sz>
    friend ostream& operator<<(ostream& out, const seqlist<U, sz>& list);
};

template<typename T, int size>
ostream& operator<<(ostream& out, const seqlist<T, size>& list) {
    for (int i = 0; i <= list.last; i++) {
        out << list.slate[i];
        if (i < list.last) out << "  ";
        if ((i + 1) % 10 == 0) out << "\n";
    }
    if ((list.last + 1) % 10 != 0) out << "\n";
    return out;
}

