    complex1() : real(0), imag(0) {}
    complex1(double r, double i) : real(r), imag(i) {}

    double modulus() const { return sqrt(real * real + imag * imag); }

    bool operator==(const complex1& o) const { return modulus() == o.modulus(); }
    bool operator<(const complex1& o) const  { return modulus() < o.modulus(); }
