#include<iostream>
#include<cmath>
#include <cstdlib>
#include <ctime>

int gcd(int a, int b) 
{
	return b == 0 ? std::abs(a) : gcd(b, a % b);
}
class MyFraction 
{
	int Numerator;					//分子
	int Denominator;				//分母
	void reduction();				//约分
	void makeCommond(MyFraction);	//将当前分数改为与形参分数通分的形式
public:
	MyFraction add(MyFraction);		//分数相加，不改变加数值，返回相加后的值
	MyFraction sub(MyFraction);		//分数相减，不改变减数和被减数，返回差值
	MyFraction mul(MyFraction);		//分数相乘，不改变乘数值，返回乘积值
	MyFraction div(MyFraction);		//分数相除，不改变减数和被减数，返回商值
	void display();					//显示分数，格式 1/3，如有负号显示在分子
	double ToDouble();				//输出分数的实数值
	MyFraction(int n = 0, int d = 1);

	void myadd(const MyFraction&);	//分数值自加
	void mysub(const MyFraction&);	//分数值自减
	void mymul(const MyFraction&);	//分数值自乘
	void mydiv(const MyFraction&);	//分数值自除
	MyFraction reciprocal();		//求当前分数的倒数
	bool equal(MyFraction&);		//比较两个分数的是否相等
	bool greaterThan(MyFraction&);	//比较两个分数值大小
	void inputFraction();			//读取键盘输入的分子分母

	// ===== 比较运算符重载 =====
	bool operator==(const MyFraction& f) const;	//相等
	bool operator!=(const MyFraction& f) const;	//不等
	bool operator< (const MyFraction& f) const;	//小于
	bool operator> (const MyFraction& f) const;	//大于
	bool operator<=(const MyFraction& f) const;	//小于等于
	bool operator>=(const MyFraction& f) const;	//大于等于
};

// ---------------------------------------------------------------
// 构造函数
// ---------------------------------------------------------------
MyFraction::MyFraction(int n, int d): Numerator(n), Denominator(d)
{
	if (d == 0)
	{
		std::cerr << "分母不能为零。" << std::endl;
		Denominator = 1;
	}
	else if (d < 0)
	{
		Numerator = -Numerator;
		Denominator = -Denominator;
	}
	else
	{
		Numerator = n;
		Denominator = d;
	}
	reduction(); 
}

// ---------------------------------------------------------------
// 约分
// ---------------------------------------------------------------
void MyFraction::reduction()
{
	if (Denominator == 0) return;
	int common = gcd(Numerator, Denominator);
	Numerator /= common;
	Denominator /= common;
	if (Denominator < 0)
	{
		Numerator = -Numerator;
		Denominator = -Denominator;
	}
}

// ---------------------------------------------------------------
// 通分（将当前分数改为与形参分数通分的形式）
// ---------------------------------------------------------------
void MyFraction::makeCommond(MyFraction f)
{
	int commonDenominator = (Denominator / gcd(Denominator, f.Denominator)) * f.Denominator;
	int factor = commonDenominator / Denominator;
	Numerator = Numerator * factor;
	Denominator = commonDenominator;
}

// ---------------------------------------------------------------
// 四则运算（返回新对象，不修改操作数）
// ---------------------------------------------------------------
MyFraction MyFraction::add(MyFraction f)
{
	MyFraction result = *this;
	int commonDen = (result.Denominator / gcd(result.Denominator, f.Denominator)) * f.Denominator;
	result.Numerator = result.Numerator * (commonDen / result.Denominator)
		+ f.Numerator * (commonDen / f.Denominator);
	result.Denominator = commonDen;
	result.reduction();
	std::cout << "("; this->display();
	std::cout << ") + ("; f.display();
	std::cout << ") = ("; result.display();
	std::cout << ")" << std::endl;
	return result;
}

MyFraction MyFraction::sub(MyFraction f)
{
	MyFraction result = *this;
	int commonDen = (result.Denominator / gcd(result.Denominator, f.Denominator)) * f.Denominator;
	result.Numerator = result.Numerator * (commonDen / result.Denominator)
		- f.Numerator * (commonDen / f.Denominator);
	result.Denominator = commonDen;
	result.reduction();
	std::cout << "("; this->display();
	std::cout << ") - ("; f.display();
	std::cout << ") = ("; result.display();
	std::cout << ")" << std::endl;
	return result;
}

MyFraction MyFraction::mul(MyFraction f)
{
	MyFraction result = *this;
	result.Numerator = result.Numerator * f.Numerator;
	result.Denominator = result.Denominator * f.Denominator;
	result.reduction();
	std::cout << "("; this->display();
	std::cout << ") * ("; f.display();
	std::cout << ") = ("; result.display();
	std::cout << ")" << std::endl;
	return result;
}

MyFraction MyFraction::div(MyFraction f)
{
	MyFraction result = *this;
	if (f.Numerator == 0) {
		std::cout << "错误：除数分子为 0，导致除零异常。" << std::endl;
		return *this;
	}
	result.Numerator = result.Numerator * f.Denominator;
	result.Denominator = result.Denominator * f.Numerator;
	result.reduction();
	std::cout << "("; this->display();
	std::cout << ") / ("; f.display();
	std::cout << ") = ("; result.display();
	std::cout << ")" << std::endl;
	return result;
}

// ---------------------------------------------------------------
// 显示 / 转实数
// ---------------------------------------------------------------
void MyFraction::display()
{
	std::cout << Numerator << "/" << Denominator;
}

double MyFraction::ToDouble()
{
	return static_cast<double>(Numerator) / Denominator;
}

// ---------------------------------------------------------------
// 自运算
// ---------------------------------------------------------------
void MyFraction::myadd(const MyFraction& f)
{
	int newNum = Numerator * f.Denominator + f.Numerator * Denominator;
	int newDen = Denominator * f.Denominator;
	Numerator = newNum; Denominator = newDen;
	this->reduction();
}

void MyFraction::mysub(const MyFraction& f)
{
	int newNum = Numerator * f.Denominator - f.Numerator * Denominator;
	int newDen = Denominator * f.Denominator;
	Numerator = newNum; Denominator = newDen;
	this->reduction();
}

void MyFraction::mymul(const MyFraction& f)
{
	int newNum = Numerator * f.Numerator;
	int newDen = Denominator * f.Denominator;
	Numerator = newNum; Denominator = newDen;
	this->reduction();
}

void MyFraction::mydiv(const MyFraction& f)
{
	int newNum = Numerator * f.Denominator;
	int newDen = Denominator * f.Numerator;
	Numerator = newNum; Denominator = newDen;
	this->reduction();
}

// ---------------------------------------------------------------
// 倒数
// ---------------------------------------------------------------
MyFraction MyFraction::reciprocal()
{
	if (Numerator == 0)
	{
		std::cout << "分数分子为零，无法求倒数";
		return *this;
	}
	MyFraction result(Denominator, Numerator);
	std::cout << "的倒数为";
	result.display();
	std::cout << std::endl;
	return result;
}

// ---------------------------------------------------------------
// 旧版比较（保留兼容）
// ---------------------------------------------------------------
bool MyFraction::equal(MyFraction& f)
{
	MyFraction result = *this;
	result.reduction(); f.reduction();
	return (result.Numerator == f.Numerator && result.Denominator == f.Denominator);
}

bool MyFraction::greaterThan(MyFraction& f)
{
	MyFraction result = *this;
	result.reduction(); f.reduction();
	if (result.Numerator * f.Denominator > result.Denominator * f.Numerator)
	{
		result.display(); std::cout << "大" << std::endl;
		return true;
	}
	else if (result.Numerator * f.Denominator < result.Denominator * f.Numerator)
	{
		f.display(); std::cout << "大" << std::endl;
		return false;
	}
	else
	{
		std::cout << "一样大" << std::endl;
		return false;
	}
}

// ---------------------------------------------------------------
// 输入
// ---------------------------------------------------------------
void MyFraction::inputFraction()
{
	int num, den;
	std::cout << "对成员 Numerator 和 Denominator 赋值：";
	if (!(std::cin >> num >> den)) return;
	if (den == 0)
	{
		std::cout << "分母不能为零" << std::endl;
		Denominator = 1;
	}
	else
	{
		Numerator = num;
		Denominator = den;
	}
}

// ===============================================================
// 比较运算符重载实现
//
// 核心思路：通分后比较分子大小，即
//   a/b  op  c/d  <==>  a*d  op  c*b  （b,d 均为正数，约分后保证）
// ===============================================================

// 相等：约分后分子分母均相同
bool MyFraction::operator==(const MyFraction& f) const
{
	// 约分已在构造 / reduction() 中保证，直接比较即可
	return (Numerator == f.Numerator && Denominator == f.Denominator);
}

// 不等：取反
bool MyFraction::operator!=(const MyFraction& f) const
{
	return !(*this == f);
}

// 小于：交叉相乘比较（分母均为正数，约分保证）
bool MyFraction::operator<(const MyFraction& f) const
{
	// a/b < c/d  <==>  a*d < c*b  （b>0, d>0）
	return (static_cast<long long>(Numerator) * f.Denominator
	      < static_cast<long long>(f.Numerator) * Denominator);
}

// 大于
bool MyFraction::operator>(const MyFraction& f) const
{
	return (f < *this);
}

// 小于等于
bool MyFraction::operator<=(const MyFraction& f) const
{
	return !(*this > f);
}

// 大于等于
bool MyFraction::operator>=(const MyFraction& f) const
{
	return !(*this < f);
}

// ---------------------------------------------------------------
// 全局对象数组
// ---------------------------------------------------------------
MyFraction fractions[] = {
	MyFraction(1, 3),
	MyFraction(1, 6),
	MyFraction(2, 4),
	MyFraction(4, 15),
	MyFraction(5, 9),
	MyFraction(1, 8)
};

// ---------------------------------------------------------------
// 辅助：打印两个分数及其比较结果
// ---------------------------------------------------------------
static void printCompare(MyFraction a, MyFraction b)
{
	a.display(); std::cout << "  vs  "; b.display(); std::cout << std::endl;
	std::cout << "  ==  : " << std::boolalpha << (a == b) << std::endl;
	std::cout << "  !=  : " << (a != b) << std::endl;
	std::cout << "  <   : " << (a <  b) << std::endl;
	std::cout << "  >   : " << (a >  b) << std::endl;
	std::cout << "  <=  : " << (a <= b) << std::endl;
	std::cout << "  >=  : " << (a >= b) << std::endl;
}

// ---------------------------------------------------------------
// main
// ---------------------------------------------------------------
int main() 
{
	// ---------- 原有自运算测试 ----------
	MyFraction f2(1, 3), f3(3, 4);
	std::cout << "===== 自运算测试 =====" << std::endl;
	std::cout << "分数"; f2.display(); std::cout << "：" << std::endl;
	std::cout << "加上"; f3.display(); std::cout << "后值为"; f2.myadd(f3); f2.display(); std::cout << std::endl;
	std::cout << "再减去"; f3.display(); std::cout << "后值为"; f2.mysub(f3); f2.display(); std::cout << std::endl;
	std::cout << "再乘以"; f3.display(); std::cout << "后值为"; f2.mymul(f3); f2.display(); std::cout << std::endl;
	std::cout << "再除以"; f3.display(); std::cout << "后值为"; f2.mydiv(f3); f2.display(); std::cout << std::endl;

	// ---------- 比较运算符重载测试 ----------
	std::cout << "\n===== 比较运算符重载测试 =====" << std::endl;

	MyFraction p(1, 3), q(1, 3);
	std::cout << "--- 相等的两个分数 ---" << std::endl;
	printCompare(p, q);

	MyFraction r(2, 6); // 化简后也是 1/3
	std::cout << "--- 2/6 与 1/3（化简后相等）---" << std::endl;
	printCompare(MyFraction(2,6), MyFraction(1,3));

	std::cout << "--- 1/3 与 1/2 ---" << std::endl;
	printCompare(MyFraction(1,3), MyFraction(1,2));

	std::cout << "--- -3/4 与 1/4 ---" << std::endl;
	printCompare(MyFraction(-3,4), MyFraction(1,4));

	std::cout << "--- 5/6 与 5/6 (相等边界) ---" << std::endl;
	printCompare(MyFraction(5,6), MyFraction(5,6));

	// ---------- 倒数测试 ----------
	std::cout << "\n===== 倒数测试 =====" << std::endl;
	for (int i = 0; i < 6; i++)
	{
		fractions[i].display();
		fractions[i].reciprocal();
	}

	return 0;
}

