xlabel('时间 (s)'); ylabel('幅度'); title('无噪声信号');
grid on; xlim([0, max(t_cw)]);

subplot(3,4,2);
plot(t_cw, cw_noisy_0dB, 'r', 'LineWidth', 0.5);
