[f_cw, S_clean] = calc_spectrum(seg_cw_clean, fs);
[~,   S_n0]     = calc_spectrum(seg_cw_n0,    fs);
[~,   S_n5]     = calc_spectrum(seg_cw_n5,    fs);
[~,   S_f0]     = calc_spectrum(seg_cw_f0,    fs);
[~,   S_f5]     = calc_spectrum(seg_cw_f5,    fs);
N_half = floor(length(f_cw)/2);

subplot(3,4,5);
plot(f_cw(1:N_half), S_clean(1:N_half), 'b');
xlabel('频率 (Hz)'); ylabel('幅度'); title('无噪声幅度谱'); grid on; xlim([0, fs/2]);

subplot(3,4,6);
plot(f_cw(1:N_half), S_n0(1:N_half), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=0dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,7);
plot(f_cw(1:N_half), S_n5(1:N_half), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=5dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,8);
