{"language": "plaintext", "code": "%% 主动探测脉冲接收信号仿真
% 实验2.1 + 2.2：信号仿真、加噪、滤波、时域/频域/时频分析
% 采样率：32kHz，脉冲起始时间：0.2s，脉冲后添加0.2s零值

clear; clc; close all;

%% ========== 全局参数 ==========
fs = 32000;          % 采样率 Hz
t_pre = 0.2;         % 前置零值时长 (s)
t_post = 0.2;        % 脉冲结束后零值时长 (s)

%% ========== 信号生成函数 ==========
% gen_lfm(f0, f1, T, fs): 生成LFM(线性调频)或CW信号
%   f0: 起始频率, f1: 终止频率, T: 脉宽, fs: 采样率
%   当 f0==f1 时退化为CW信号

gen_pulse = @(f0, f1, T) ...
    chirp(0:1/fs:T-1/fs, f0, T, f1);

%% ========== 2.1(1) 发射信号仿真 ==========

%% -- 表1：单脉冲信号 --

% CW: 3200Hz, 脉宽1s
cw_pulse   = gen_pulse(3200, 3200, 1);
n_pre      = round(t_pre * fs);
n_post     = round(t_post * fs);
cw_signal  = [zeros(1, n_pre), cw_pulse, zeros(1, n_post)];
t_cw       = (0:length(cw_signal)-1) / fs;

% LFM: 3000-3400Hz, 脉宽2s
lfm_pulse  = gen_pulse(3000, 3400, 2);
lfm_signal = [zeros(1, n_pre), lfm_pulse, zeros(1, n_post)];
t_lfm      = (0:length(lfm_signal)-1) / fs;

%% -- 表2：组合脉冲信号 --
% 子脉冲1: 2000-2500Hz, 2s
% 子脉冲2: 2100-2100Hz, 1s, 间隔0s
% 子脉冲3: 2300-2600Hz, 1.5s, 间隔0s
sub1 = gen_pulse(2000, 2500, 2);
sub2 = gen_pulse(2100, 2100, 1);
sub3 = gen_pulse(2300, 2600, 1.5);
% 间隔均为0，直接拼接
combo_pulse  = [sub1, sub2, sub3];
combo_signal = [zeros(1, n_pre), combo_pulse, zeros(1, n_post)];
t_combo      = (0:length(combo_signal)-1) / fs;

%% ========== 2.1(2) 添加背景噪声 ==========
% SNR = 10*lg(A^2 / (2*sigma^2))
% => sigma = A / sqrt(2 * 10^(SNR/10))

add_noise = @(sig, snr_dB) ...
    sig + (max(abs(sig)) / sqrt(2 * 10^(snr_dB/10))) * randn(1, length(sig));

% CW信号加噪
cw_noisy_0dB = add_noise(cw_signal, 0);
cw_noisy_5dB = add_noise(cw_signal, 5);

% LFM信号加噪
lfm_noisy_0dB = add_noise(lfm_signal, 0);
lfm_noisy_5dB = add_noise(lfm_signal, 5);

% 组合信号加噪
combo_noisy_0dB = add_noise(combo_signal, 0);
combo_noisy_5dB = add_noise(combo_signal, 5);

%% ========== FIR带通滤波器设计 ==========
% 根据各信号频带设计，Kaiser窗FIR带通

design_fir_bp = @(flo, fhi, fs) ...
    fir1(256, [flo/(fs/2), fhi/(fs/2)], 'bandpass', kaiser(257, 6));

% CW带通滤波器: 3100-3300 Hz
b_cw    = design_fir_bp(3100, 3300, fs);
% LFM带通滤波器: 2900-3500 Hz
b_lfm   = design_fir_bp(2900, 3500, fs);
% 组合带通滤波器: 1900-2700 Hz
b_combo = design_fir_bp(1900, 2700, fs);

% 滤波（0dB加噪信号作为演示）
cw_filt_0dB    = filtfilt(b_cw,    1, cw_noisy_0dB);
cw_filt_5dB    = filtfilt(b_cw,    1, cw_noisy_5dB);
lfm_filt_0dB   = filtfilt(b_lfm,   1, lfm_noisy_0dB);
lfm_filt_5dB   = filtfilt(b_lfm,   1, lfm_noisy_5dB);
combo_filt_0dB = filtfilt(b_combo, 1, combo_noisy_0dB);
combo_filt_5dB = filtfilt(b_combo, 1, combo_noisy_5dB);

%% ========== 2.2 可视化分析 ==========

%% ---- 辅助函数 ----

% 幅度谱计算
calc_spectrum = @(sig, fs) deal( ...
    (0:length(sig)-1)/length(sig)*fs, ...
    abs(fft(sig))/length(sig) );

% STFT时频图绘制
plot_stft = @(sig, fs, win_len, overlap, nfft, ax) ...
    spectrogram(sig, hanning(win_len), overlap, nfft, fs, 'yaxis');

%% ===========================
%% 图组1：CW单脉冲信号
%% ===========================
figure('Name','CW单脉冲信号分析','Position',[50,50,1400,900]);
sgtitle('CW单脉冲信号 (3200Hz, 脉宽1s)', 'FontSize', 14, 'FontWeight', 'bold');

% --- 时域分析 ---
% SNR=0dB
subplot(3,4,1);
plot(t_cw, cw_signal, 'b', 'LineWidth', 1);
xlabel('时间 (s)'); ylabel('幅度'); title('无噪声信号');
grid on; xlim([0, max(t_cw)]);

subplot(3,4,2);
plot(t_cw, cw_noisy_0dB, 'r', 'LineWidth', 0.5);
xlabel('时间 (s)'); ylabel('幅度'); title('加噪信号 (SNR=0dB)');
grid on; xlim([0, max(t_cw)]);

subplot(3,4,3);
plot(t_cw, cw_noisy_5dB, 'r', 'LineWidth', 0.5);
xlabel('时间 (s)'); ylabel('幅度'); title('加噪信号 (SNR=5dB)');
grid on; xlim([0, max(t_cw)]);

subplot(3,4,4);
plot(t_cw, cw_filt_0dB, 'g', 'LineWidth', 1); hold on;
plot(t_cw, cw_filt_5dB, 'm', 'LineWidth', 1);
xlabel('时间 (s)'); ylabel('幅度'); title('滤波后信号');
legend('0dB滤波','5dB滤波'); grid on; xlim([0, max(t_cw)]);

% --- 频域分析（截取脉冲段）---
idx_cw = round(t_pre*fs)+1 : round((t_pre+1)*fs);  % 脉冲段索引
seg_cw_clean = cw_signal(idx_cw);
seg_cw_n0    = cw_noisy_0dB(idx_cw);
seg_cw_n5    = cw_noisy_5dB(idx_cw);
seg_cw_f0    = cw_filt_0dB(idx_cw);
seg_cw_f5    = cw_filt_5dB(idx_cw);

[f_cw, S_clean] = calc_spectrum(seg_cw_clean, fs);
[~,   S_n0]     = calc_spectrum(seg_cw_n0,    fs);
[~,   S_n5]     = calc_spectrum(seg_cw_n5,    fs);
[~,   S_f0]     = calc_spectrum(seg_cw_f0,    fs);
[~,   S_f5]     = calc_spectrum(seg_cw_f5,    fs);
N_half = floor(length(f_cw)/2);

subplot(3,4,5);
plot(f_cw(1:N_half), S_clean(1:N_half), 'b');
xlabel('频率 (Hz)'); ylabel('幅度'); title('无噪声幅度谱'); grid on; xlim([0, fs/2]);

subplot(3,4,6);
plot(f_cw(1:N_half), S_n0(1:N_half), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=0dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,7);
plot(f_cw(1:N_half), S_n5(1:N_half), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=5dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,8);
plot(f_cw(1:N_half), S_f0(1:N_half), 'g'); hold on;
plot(f_cw(1:N_half), S_f5(1:N_half), 'm');
xlabel('频率 (Hz)'); ylabel('幅度'); title('滤波后幅度谱');
legend('0dB','5dB'); grid on; xlim([0, fs/2]);

% --- 时频分析 (STFT) ---
win_cw = 512; ovlp_cw = 480; nfft_cw = 1024;

subplot(3,4,9);
spectrogram(cw_signal, hanning(win_cw), ovlp_cw, nfft_cw, fs, 'yaxis');
title('无噪声 STFT时频图'); colorbar; ylim([0, 8]);

subplot(3,4,10);
spectrogram(cw_noisy_0dB, hanning(win_cw), ovlp_cw, nfft_cw, fs, 'yaxis');
title('加噪 STFT (SNR=0dB)'); colorbar; ylim([0, 8]);

subplot(3,4,11);
spectrogram(cw_noisy_5dB, hanning(win_cw), ovlp_cw, nfft_cw, fs, 'yaxis');
title('加噪 STFT (SNR=5dB)'); colorbar; ylim([0, 8]);

subplot(3,4,12);
spectrogram(cw_filt_0dB, hanning(win_cw), ovlp_cw, nfft_cw, fs, 'yaxis');
title('滤波后 STFT (0dB)'); colorbar; ylim([0, 8]);

%% ===========================
%% 图组2：LFM单脉冲信号
%% ===========================
figure('Name','LFM单脉冲信号分析','Position',[80,80,1400,900]);
sgtitle('LFM单脉冲信号 (3000-3400Hz, 脉宽2s)', 'FontSize', 14, 'FontWeight', 'bold');

% --- 时域 ---
subplot(3,4,1);
plot(t_lfm, lfm_signal, 'b', 'LineWidth', 1);
xlabel('时间 (s)'); ylabel('幅度'); title('无噪声信号');
grid on; xlim([0, max(t_lfm)]);

subplot(3,4,2);
plot(t_lfm, lfm_noisy_0dB, 'r', 'LineWidth', 0.5);
xlabel('时间 (s)'); ylabel('幅度'); title('加噪信号 (SNR=0dB)');
grid on; xlim([0, max(t_lfm)]);

subplot(3,4,3);
plot(t_lfm, lfm_noisy_5dB, 'r', 'LineWidth', 0.5);
xlabel('时间 (s)'); ylabel('幅度'); title('加噪信号 (SNR=5dB)');
