subplot(3,4,4);
plot(t_lfm, lfm_filt_0dB, 'g', 'LineWidth', 1); hold on;
plot(t_lfm, lfm_filt_5dB, 'm', 'LineWidth', 1);
xlabel('时间 (s)'); ylabel('幅度'); title('滤波后信号');
legend('0dB','5dB'); grid on; xlim([0, max(t_lfm)]);

% --- 频域（截取脉冲段）---
idx_lfm = round(t_pre*fs)+1 : round((t_pre+2)*fs);
seg_lfm_clean = lfm_signal(idx_lfm);
seg_lfm_n0    = lfm_noisy_0dB(idx_lfm);
seg_lfm_n5    = lfm_noisy_5dB(idx_lfm);
