xlabel('时间 (s)'); ylabel('幅度'); title('加噪信号 (SNR=0dB)');
grid on; xlim([0, max(t_combo)]);

subplot(3,4,3);
plot(t_combo, combo_noisy_5dB, 'r', 'LineWidth', 0.5);
