% --- 频域（截取整个脉冲段）---
idx_combo = round(t_pre*fs)+1 : round((t_pre+4.5)*fs);
seg_combo_clean = combo_signal(idx_combo);
seg_combo_n0    = combo_noisy_0dB(idx_combo);
