seg_combo_f5    = combo_filt_5dB(idx_combo);

[f_combo, SC_clean] = calc_spectrum(seg_combo_clean, fs);
[~,       SC_n0]    = calc_spectrum(seg_combo_n0,    fs);
[~,       SC_n5]    = calc_spectrum(seg_combo_n5,    fs);
