N_half_c = floor(length(f_combo)/2);

subplot(3,4,5);
plot(f_combo(1:N_half_c), SC_clean(1:N_half_c), 'b');
xlabel('频率 (Hz)'); ylabel('幅度'); title('无噪声幅度谱'); grid on; xlim([0, fs/2]);

subplot(3,4,6);
plot(f_combo(1:N_half_c), SC_n0(1:N_half_c), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=0dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,7);
plot(f_combo(1:N_half_c), SC_n5(1:N_half_c), 'r');
xlabel('频率 (Hz)'); ylabel('幅度'); title('加噪幅度谱 (SNR=5dB)'); grid on; xlim([0, fs/2]);

subplot(3,4,8);
plot(f_combo(1:N_half_c), SC_f0(1:N_half_c), 'g'); hold on;
plot(f_combo(1:N_half_c), SC_f5(1:N_half_c), 'm');
xlabel('频率 (Hz)'); ylabel('幅度'); title('滤波后幅度谱');
legend('0dB','5dB'); grid on; xlim([0, fs/2]);

% --- 时频 ---
win_c = 512; ovlp_c = 480; nfft_c = 1024;

subplot(3,4,9);
spectrogram(combo_signal, hanning(win_c), ovlp_c, nfft_c, fs, 'yaxis');
title('无噪声 STFT时频图'); colorbar; ylim([0, 8]);

subplot(3,4,10);
