title('滤波后 STFT (0dB)'); colorbar; ylim([0, 8]);

%% ===========================
%% 额外：独立大图——三种信号STFT时频图对比
%% ===========================
figure('Name','三种信号STFT时频对比','Position',[140,140,1400,500]);
