subplot(1,3,3);
spectrogram(combo_signal, hanning(512), 480, 1024, fs, 'yaxis');
title('组合脉冲'); colorbar; ylim([0, 8]);
xlabel('时间 (s)'); ylabel('频率 (kHz)');

