%% 主动探测脉冲信号特性分析
% 任务1.1 + 1.2 完整仿真代码
% 参数：fs=17941 Hz, CW(f0=3980.1Hz,τ=1.9s), LFM/HFM(f1=1405Hz,f2=2164.3Hz,τ=1.7s)
%       组合脉冲：LFM-CW-HFM

clear; close all; clc;

%% ========== 基本参数设置 ==========
fs   = 17941;       % 采样频率 (Hz)
f0   = 3980.1;      % CW 中心频率 (Hz)
tau1 = 1.9;         % CW 脉冲宽度 (s)
f1   = 1405.0;      % LFM/HFM 起始频率 (Hz)
f2   = 2164.3;      % LFM/HFM 终止频率 (Hz)
tau2 = 1.7;         % LFM/HFM 脉冲宽度 (s)

%% ========== 1. 生成三组信号 ==========

%--- 第1组：CW 单频脉冲 ---
t1 = (0 : 1/fs : tau1 - 1/fs)';
s_cw = cos(2*pi*f0*t1);

%--- 第2组：LFM 线性调频 ---
t2 = (0 : 1/fs : tau2 - 1/fs)';
k_lfm = (f2 - f1) / tau2;          % 调频斜率 (Hz/s)
s_lfm = cos(2*pi*(f1*t2 + 0.5*k_lfm*t2.^2));

%--- 第2组：HFM 双曲调频（Hyperbolic FM） ---
% 瞬时频率: f(t) = f1*f2*tau2 / (f2*tau2 - (f2-f1)*t)
% 相位积分: phi(t) = -2*pi*f1*f2*tau2/(f2-f1) * ln(1-(f2-f1)/(f2*tau2)*t)
BW   = f2 - f1;
phi_hfm = -2*pi*f1*f2*tau2/BW * log(1 - BW/(f2*tau2)*t2);
s_hfm = cos(phi_hfm);

%--- 第3组：组合脉冲 LFM - CW - HFM（各子脉冲等长，拼接） ---
% 子脉冲时长统一取 tau2=1.7s（保持与第2组一致）
t_sub = (0 : 1/fs : tau2 - 1/fs)';
% LFM 子脉冲
sub_lfm = cos(2*pi*(f1*t_sub + 0.5*k_lfm*t_sub.^2));
% CW 子脉冲（使用 f0）
sub_cw  = cos(2*pi*f0*t_sub);
% HFM 子脉冲
phi_hfm_sub = -2*pi*f1*f2*tau2/BW * log(1 - BW/(f2*tau2)*t_sub);
sub_hfm = cos(phi_hfm_sub);
% 拼接
s_combo = [sub_lfm; sub_cw; sub_hfm];
t_combo = (0 : length(s_combo)-1)' / fs;

%% ========== 2. 任务1.1：时域波形图 ==========
figure('Name','时域波形','Position',[100 100 1400 800]);

subplot(3,1,1);
plot(t1, s_cw, 'b', 'LineWidth', 0.8);
xlabel('时间 t (s)'); ylabel('幅度');
title(sprintf('第1组 CW 脉冲信号（f_0 = %.1f Hz，\\tau = %.1f s）', f0, tau1));
xlim([0 tau1]); ylim([-1.3 1.3]);
grid on;

subplot(3,1,2);
plot(t2, s_lfm, 'r', 'LineWidth', 0.8);
xlabel('时间 t (s)'); ylabel('幅度');
title(sprintf('第2组 LFM 脉冲信号（f_1=%.1f Hz，f_2=%.1f Hz，\\tau=%.1f s）', f1, f2, tau2));
xlim([0 tau2]); ylim([-1.3 1.3]);
grid on;

subplot(3,1,3);
plot(t2, s_hfm, 'm', 'LineWidth', 0.8);
xlabel('时间 t (s)'); ylabel('幅度');
title(sprintf('第2组 HFM 脉冲信号（f_1=%.1f Hz，f_2=%.1f Hz，\\tau=%.1f s）', f1, f2, tau2));
xlim([0 tau2]); ylim([-1.3 1.3]);
grid on;

sgtitle('任务1.1 — 时域波形图', 'FontSize', 14, 'FontWeight', 'bold');

%% ========== 3. 任务1.1：频谱图 ==========
figure('Name','频谱图','Position',[100 100 1400 800]);

% CW 频谱
N1 = length(s_cw);
S_cw = abs(fft(s_cw, N1)) / N1;
S_cw = S_cw(1:floor(N1/2)+1);
S_cw(2:end-1) = 2*S_cw(2:end-1);
f_ax1 = (0:floor(N1/2)) * fs / N1;

subplot(3,1,1);
plot(f_ax1, 20*log10(S_cw + 1e-12), 'b', 'LineWidth', 1);
xlabel('频率 f (Hz)'); ylabel('幅度谱 (dB)');
title(sprintf('第1组 CW 频谱（峰值频率约 %.1f Hz）', f0));
xlim([0 fs/2]); grid on;
xline(f0, 'k--', sprintf('f_0=%.1f Hz', f0), 'LabelVerticalAlignment','bottom');

% LFM 频谱
N2 = length(s_lfm);
S_lfm = abs(fft(s_lfm, N2)) / N2;
S_lfm = S_lfm(1:floor(N2/2)+1);
S_lfm(2:end-1) = 2*S_lfm(2:end-1);
f_ax2 = (0:floor(N2/2)) * fs / N2;

subplot(3,1,2);
plot(f_ax2, 20*log10(S_lfm + 1e-12), 'r', 'LineWidth', 1);
xlabel('频率 f (Hz)'); ylabel('幅度谱 (dB)');
title(sprintf('第2组 LFM 频谱（带宽 %.1f Hz）', f2-f1));
xlim([0 fs/2]); grid on;
xline(f1, 'k--', sprintf('f_1=%.1f Hz', f1), 'LabelVerticalAlignment','bottom');
xline(f2, 'k-.', sprintf('f_2=%.1f Hz', f2), 'LabelVerticalAlignment','bottom');

% HFM 频谱
S_hfm = abs(fft(s_hfm, N2)) / N2;
S_hfm = S_hfm(1:floor(N2/2)+1);
S_hfm(2:end-1) = 2*S_hfm(2:end-1);

subplot(3,1,3);
plot(f_ax2, 20*log10(S_hfm + 1e-12), 'm', 'LineWidth', 1);
xlabel('频率 f (Hz)'); ylabel('幅度谱 (dB)');
title(sprintf('第2组 HFM 频谱（带宽 %.1f Hz）', f2-f1));
xlim([0 fs/2]); grid on;
xline(f1, 'k--', sprintf('f_1=%.1f Hz', f1), 'LabelVerticalAlignment','bottom');
xline(f2, 'k-.', sprintf('f_2=%.1f Hz', f2), 'LabelVerticalAlignment','bottom');

sgtitle('任务1.1 — 频谱图（单边幅度谱）', 'FontSize', 14, 'FontWeight', 'bold');

%% ========== 4. 组合脉冲时域 + 频谱 ==========
figure('Name','组合脉冲','Position',[100 100 1200 600]);

subplot(2,1,1);
plot(t_combo, s_combo, 'k', 'LineWidth', 0.7);
xlabel('时间 t (s)'); ylabel('幅度');
title('第3组 组合脉冲（LFM—CW—HFM）时域波形');
xlim([0 t_combo(end)]);
% 标注子脉冲分界
xline(tau2,   'b--', 'LFM|CW', 'LabelVerticalAlignment','bottom');
xline(2*tau2, 'r--', 'CW|HFM', 'LabelVerticalAlignment','bottom');
grid on;

Nc = length(s_combo);
S_combo = abs(fft(s_combo, Nc)) / Nc;
S_combo = S_combo(1:floor(Nc/2)+1);
S_combo(2:end-1) = 2*S_combo(2:end-1);
f_axc = (0:floor(Nc/2)) * fs / Nc;

subplot(2,1,2);
plot(f_axc, 20*log10(S_combo + 1e-12), 'k', 'LineWidth', 1);
xlabel('频率 f (Hz)'); ylabel('幅度谱 (dB)');
title('第3组 组合脉冲频谱');
xlim([0 fs/2]); grid on;

sgtitle('任务1.1 — 第3组 组合脉冲（LFM-CW-HFM）', 'FontSize', 14, 'FontWeight', 'bold');

%% ========== 5. 任务1.2：STFT 时频分析 ==========
% 参数设计：窗长建议为信号时长的 1/10 ~ 1/20，步进为窗长的 1/4

fprintf('\n===== STFT 参数 =====\n');

% --- 窗长选择（短窗 vs 长窗）---
win_short = round(0.05 * fs);   % 短窗 ≈ 50ms
win_long  = round(0.20 * fs);   % 长窗 ≈ 200ms

step_short = round(win_short / 4);
step_long  = round(win_long  / 4);

nfft = 2^nextpow2(win_long * 2); % 统一 NFFT

fprintf('短窗长 = %d 点（%.1f ms），步进 = %d 点\n', win_short, win_short/fs*1e3, step_short);
fprintf('长窗长 = %d 点（%.1f ms），步进 = %d 点\n', win_long,  win_long/fs*1e3,  step_long);
fprintf('NFFT   = %d\n', nfft);

%--- 辅助函数：计算并绘制 STFT ---
% (内联实现，避免依赖 Signal Processing Toolbox 的 spectrogram 函数)

    function [S_mat, t_vec, f_vec] = my_stft(x, win_len, step, nfft_pts, fs_hz)
        win   = hann(win_len);
        N     = length(x);
        n_frames = floor((N - win_len) / step) + 1;
        S_mat = zeros(floor(nfft_pts/2)+1, n_frames);
        for k = 1:n_frames
            idx   = (k-1)*step + (1:win_len);
            frame = x(idx) .* win;
            X     = fft(frame, nfft_pts);
            S_mat(:,k) = abs(X(1:floor(nfft_pts/2)+1));
        end
        t_vec = ((0:n_frames-1)*step + win_len/2) / fs_hz;
        f_vec = (0:floor(nfft_pts/2)) * fs_hz / nfft_pts;
    end

%% 5.1 CW 信号 STFT（短窗）
[S_cw_stft, t_s, f_s] = my_stft(s_cw, win_short, step_short, nfft, fs);
figure('Name','CW STFT','Position',[100 100 900 400]);
imagesc(t_s, f_s/1e3, 20*log10(S_cw_stft + 1e-12));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('CW 时频图（STFT，短窗 %d 点 = %.0f ms，步进 %d 点）', win_short, win_short/fs*1e3, step_short));
ylim([0 fs/2/1e3]);
clim_auto(gca);

%% 5.2 LFM 信号 STFT（短窗 vs 长窗对比）
[S_lfm_s, t_ls, f_ls] = my_stft(s_lfm, win_short, step_short, nfft, fs);
[S_lfm_l, t_ll, f_ll] = my_stft(s_lfm, win_long,  step_long,  nfft, fs);

figure('Name','LFM STFT 短窗vs长窗','Position',[100 100 1400 500]);
subplot(1,2,1);
imagesc(t_ls, f_ls/1e3, 20*log10(S_lfm_s + 1e-12));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('LFM STFT 短窗（%d 点 = %.0f ms，步进 %d 点）', win_short, win_short/fs*1e3, step_short));
ylim([0 fs/2/1e3]); clim_auto(gca);

subplot(1,2,2);
imagesc(t_ll, f_ll/1e3, 20*log10(S_lfm_l + 1e-12));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('LFM STFT 长窗（%d 点 = %.0f ms，步进 %d 点）', win_long, win_long/fs*1e3, step_long));
ylim([0 fs/2/1e3]); clim_auto(gca);

sgtitle('任务1.2 — LFM 短窗 vs 长窗时频分辨率对比', 'FontSize', 13, 'FontWeight', 'bold');

%% 5.3 HFM 信号 STFT（短窗）
[S_hfm_stft, t_h, f_h] = my_stft(s_hfm, win_short, step_short, nfft, fs);
figure('Name','HFM STFT','Position',[100 100 900 400]);
imagesc(t_h, f_h/1e3, 20*log10(S_hfm_stft + 1e-12));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('HFM 时频图（STFT，短窗 %d 点 = %.0f ms，步进 %d 点）', win_short, win_short/fs*1e3, step_short));
ylim([0 fs/2/1e3]); clim_auto(gca);

%% 5.4 组合脉冲 STFT
[S_cb, t_cb, f_cb] = my_stft(s_combo, win_short, step_short, nfft, fs);
figure('Name','组合脉冲 STFT','Position',[100 100 1100 450]);
imagesc(t_cb, f_cb/1e3, 20*log10(S_cb + 1e-12));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('组合脉冲（LFM-CW-HFM）时频图（STFT，窗 %d 点）', win_short));
ylim([0 fs/2/1e3]); clim_auto(gca);
% 标注子脉冲分界线
xline(tau2,   'w--', 'LFM|CW',  'LabelVerticalAlignment','top', 'LineWidth', 1.5);
xline(2*tau2, 'w--', 'CW|HFM',  'LabelVerticalAlignment','top', 'LineWidth', 1.5);

%% ========== 6. 任务1.2：WVD 时频分析（与 STFT 对比） ==========
% 采用伪 Wigner-Ville 分布（PWVD）对 LFM 信号进行对比分析
% PWVD：对解析信号计算，加窗抑制交叉项

fprintf('\n===== WVD 对比分析（LFM 信号）=====\n');

% 取较短片段加快计算（前 0.5 s）
seg_len  = round(0.5 * fs);
s_seg    = s_lfm(1:seg_len);
t_seg    = t2(1:seg_len);

% 解析信号（Hilbert 变换）
za = hilbert(s_seg);
N_wvd = length(za);

% 窗函数（汉宁窗，抑制交叉项）
win_wvd_len = round(0.05 * fs);   % 50ms
if mod(win_wvd_len, 2) == 0
    win_wvd_len = win_wvd_len + 1;
end
win_wvd = hann(win_wvd_len);
half_w  = floor(win_wvd_len/2);

% 频率轴（只取正频率）
f_wvd = (0:floor(N_wvd/2)) * fs / N_wvd;
PWVD  = zeros(floor(N_wvd/2)+1, N_wvd);

for n = 1:N_wvd
    % 可用的时延范围
    tau_max = min([n-1, N_wvd-n, half_w]);
    taus    = -tau_max : tau_max;
    R       = zeros(N_wvd, 1);
    for tau = taus
        w_idx = tau + half_w + 1;
        R(tau + N_wvd/2 + 1) = win_wvd(w_idx) * za(n+tau) * conj(za(n-tau));
    end
    wvd_col = fft(R);
    PWVD(:,n) = real(wvd_col(1:floor(N_wvd/2)+1));
end

figure('Name','WVD vs STFT 对比','Position',[100 100 1400 500]);

subplot(1,2,1);
imagesc(t_seg, f_ls/1e3, 20*log10(abs(S_lfm_s(:,1:size(PWVD,2))+1e-12)));
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title(sprintf('LFM STFT（短窗 %d 点，前 0.5 s）', win_short));
ylim([0 fs/2/1e3]); clim_auto(gca);

subplot(1,2,2);
imagesc(t_seg, f_wvd/1e3, PWVD);
axis xy; colormap jet; colorbar;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title('LFM 伪 WVD（PWVD，前 0.5 s）');
ylim([0 fs/2/1e3]);
clim_vals = prctile(PWVD(:), [2 98]);
clim([clim_vals(1) clim_vals(2)]);

sgtitle('任务1.2 — STFT vs PWVD 时频对比（LFM 信号前 0.5 s）', 'FontSize', 13, 'FontWeight', 'bold');

fprintf('\n对比结论：\n');
fprintf('  STFT：时频分辨率受测不准原理限制，短窗时间分辨率好但频率分辨率差，\n');
fprintf('        长窗反之；LFM 调频线条较宽。\n');
fprintf('  PWVD：理论时频分辨率更高，LFM 的调频轨迹更锐利清晰，\n');
fprintf('        但对非线性FM或多分量信号存在交叉项干扰。\n');
fprintf('  结论：单分量调频信号推荐 PWVD；多分量或实时处理推荐 STFT。\n\n');

%% ========== 辅助函数：自动调整色度范围 ==========
    function clim_auto(ax)
        % 取图像数据非 -inf 部分的 2%~98% 分位数作为色度范围
        img_data = get(ax.Children(end), 'CData');
        finite_vals = img_data(isfinite(img_data));
        if ~isempty(finite_vals)
            clim(ax, [prctile(finite_vals,2) prctile(finite_vals,98)]);
        end
    end

fprintf('===== 所有图形绘制完毕 =====\n');

