%% 任务2：主动探测脉冲信号检测、类型辨识与参数估计
% 2.1 基于STFT的检测与类型判别方法设计与验证
% 2.2 CW脉冲信号频率估计（纯信号s.mat与含噪信号x.mat，fs=20kHz，SNR=-3dB）
%
% 运行前请将 s.mat 和 x.mat 放置在当前工作目录，或修改下方路径。

clear; close all; clc;

%% ============================================================
%  §2.1  脉冲信号检测与类型判别方法设计与验证
%  （基于任务1.1中仿真的三类信号进行验证）
%% ============================================================

fprintf('========== §2.1 脉冲信号检测与类型判别 ==========\n\n');

%% —— 重新生成任务1中的三类信号 ——
fs_sim = 17941;
f0     = 3980.1;   tau_cw  = 1.9;
f1_lf  = 1405.0;   f2_lf   = 2164.3;  tau_fm  = 1.7;
BW     = f2_lf - f1_lf;

t_cw  = (0:1/fs_sim:tau_cw-1/fs_sim)';
s_cw  = cos(2*pi*f0*t_cw);

t_fm  = (0:1/fs_sim:tau_fm-1/fs_sim)';
k_lfm = (f2_lf-f1_lf)/tau_fm;
s_lfm = cos(2*pi*(f1_lf*t_fm + 0.5*k_lfm*t_fm.^2));

phi_hfm = -2*pi*f1_lf*f2_lf*tau_fm/BW * log(1 - BW/(f2_lf*tau_fm)*t_fm);
s_hfm   = cos(phi_hfm);

t_sub   = t_fm;
sub_lfm = s_lfm;
sub_cw  = cos(2*pi*f0*t_sub);
sub_hfm = s_hfm;
s_combo = [sub_lfm; sub_cw; sub_hfm];
t_combo = (0:length(s_combo)-1)'/fs_sim;

% 加白噪声（SNR = 5 dB，验证检测鲁棒性）
snr_val  = 5;   % dB
noise_cw  = randn(size(s_cw))  * sqrt(mean(s_cw.^2)  / 10^(snr_val/10));
noise_combo = randn(size(s_combo)) * sqrt(mean(s_combo.^2) / 10^(snr_val/10));
s_cw_n    = s_cw    + noise_cw;
s_combo_n = s_combo + noise_combo;

%% —— STFT 辅助函数 ——
    function [Smag, t_vec, f_vec] = my_stft(x, win_len, step, nfft_pts, fs_hz)
        win     = hann(win_len);
        N       = length(x);
        n_frames = floor((N - win_len)/step) + 1;
        Smag    = zeros(floor(nfft_pts/2)+1, n_frames);
        for ki = 1:n_frames
            idx   = (ki-1)*step + (1:win_len);
            frame = x(idx) .* win;
            X     = fft(frame, nfft_pts);
            Smag(:,ki) = abs(X(1:floor(nfft_pts/2)+1));
        end
        t_vec = ((0:n_frames-1)*step + win_len/2) / fs_hz;
        f_vec = (0:floor(nfft_pts/2)) * fs_hz / nfft_pts;
    end

win_len  = round(0.05*fs_sim);   % 50 ms
step_len = round(win_len/4);
nfft_s   = 2^nextpow2(win_len*2);

%% —— 步骤1：脉冲信号检测（基于时域能量检测 + STFT 帧能量）——
%
% 原理：
%   对 STFT 每一帧计算频带内总能量 E(m)，
%   设置自适应门限 T = μ_noise + k·σ_noise（k=3~5），
%   当连续若干帧 E(m) > T 时判定为脉冲存在。
%
%   检测流程（CFAR-like）：
%   1. 对每帧 STFT 幅度谱求能量 E(m) = Σ|S(f,m)|²
%   2. 选取无信号区段（前/后静默段）估计噪声统计量 μ_noise, σ_noise
%   3. 门限 T = μ_noise + k·σ_noise
%   4. 寻找 E(m) > T 的帧段，确定起止时间 → 脉冲检测结果

% 在组合脉冲前加 0.3 s 静默（纯噪声）用于演示检测
t_silence = 0.3;
N_silence = round(t_silence * fs_sim);
noise_floor = 0.08 * randn(N_silence, 1);
s_detect = [noise_floor; s_combo_n];
t_detect = (0:length(s_detect)-1)'/fs_sim;

[E_stft, t_e, f_e] = my_stft(s_detect, win_len, step_len, nfft_s, fs_sim);
frame_energy = sum(E_stft.^2, 1)';   % 每帧总能量

% 用前若干帧（静默段）估计噪声能量统计
n_noise_frames = round(t_silence*fs_sim / step_len) - 2;
n_noise_frames = max(n_noise_frames, 5);
mu_n  = mean(frame_energy(1:n_noise_frames));
sig_n = std(frame_energy(1:n_noise_frames));
k_cfar = 4;
threshold = mu_n + k_cfar * sig_n;

detect_flag = frame_energy > threshold;   % 1=有信号

% 找脉冲起止时间
edges = diff([0; detect_flag; 0]);
t_start_det = t_e(edges(1:end-1) == 1);
t_end_det   = t_e(edges(2:end)   == -1);

fprintf('【检测结果】\n');
fprintf('  噪声帧均值 = %.2f，标准差 = %.2f，门限 T = %.2f（k=%d）\n', ...
        mu_n, sig_n, threshold, k_cfar);
for di = 1:length(t_start_det)
    fprintf('  脉冲 #%d：起始 %.3f s，终止 %.3f s，时长 %.3f s\n', ...
            di, t_start_det(di), t_end_det(di), t_end_det(di)-t_start_det(di));
end

% 绘制检测图
figure('Name','2.1 脉冲检测','Position',[80 80 1200 600]);
subplot(2,1,1);
plot(t_detect, s_detect, 'Color',[0.3 0.5 0.8], 'LineWidth',0.5);
xlabel('时间 t (s)'); ylabel('幅度');
title('待检测信号（静默段 + 组合脉冲，SNR=5 dB）');
grid on;
for di = 1:length(t_start_det)
    xregion(t_start_det(di), t_end_det(di), ...
            'FaceColor',[1 0.6 0.1], 'FaceAlpha',0.25);
end

subplot(2,1,2);
plot(t_e, frame_energy, 'b', 'LineWidth', 1); hold on;
yline(threshold, 'r--', sprintf('门限 T=%.1f（k=%d）', threshold, k_cfar), ...
      'LineWidth', 1.5);
for di = 1:length(t_start_det)
    xregion(t_start_det(di), t_end_det(di), ...
            'FaceColor',[1 0.6 0.1], 'FaceAlpha',0.25);
end
xlabel('时间 t (s)'); ylabel('帧能量 E(m)');
title('STFT 帧能量 + 自适应门限检测');
legend('帧能量','门限 T','检测区间'); grid on;
sgtitle('§2.1 — 步骤1：脉冲信号检测（CFAR-like 能量检测）', ...
        'FontSize',13,'FontWeight','bold');

%% —— 步骤2：类型判别（CW / LFM / HFM / 组合） ——
%
% 判别特征：
%   F1: 频带宽度 BW_hat = f_max_active - f_min_active
%       CW → BW ≈ 0（单频）
%       LFM/HFM → BW > 阈值
%
%   F2: 调频线性度 R²（对瞬时频率 vs 时间做线性回归）
%       LFM → R² ≈ 1（线性）
%       HFM → R² < 阈值（非线性）
%
%   F3: 多段分析（组合脉冲 → 不同子段特征不同）
%
% 判别规则（基于阈值）：
%   BW_hat < BW_thresh             → CW
%   BW_hat ≥ BW_thresh, R² ≥ R²_thresh → LFM
%   BW_hat ≥ BW_thresh, R² < R²_thresh → HFM
%   （组合脉冲需先分段再对每段分类）

fprintf('\n【类型判别】\n');

BW_thresh = 200;   % Hz，带宽判别阈值
R2_thresh  = 0.95; % 线性度判别阈值

signals   = {s_cw, s_lfm, s_hfm};
sig_names = {'CW', 'LFM', 'HFM'};
true_labels = {'CW', 'LFM', 'HFM'};

figure('Name','2.1 类型判别','Position',[80 80 1400 700]);
for si = 1:3
    sig   = signals{si};
    ts    = (0:length(sig)-1)'/fs_sim;
    [Sm, tm, fm] = my_stft(sig, win_len, step_len, nfft_s, fs_sim);

    % 每帧峰值频率（瞬时频率估计）
    [~, peak_idx] = max(Sm, [], 1);
    f_inst = fm(peak_idx)';

    % 带宽估计（5%能量边界）
    mean_spec = mean(Sm, 2);
    cum_en    = cumsum(mean_spec.^2) / sum(mean_spec.^2);
    f_lo = fm(find(cum_en > 0.05, 1, 'first'));
    f_hi = fm(find(cum_en < 0.95, 1, 'last'));
    BW_hat = f_hi - f_lo;

    % 线性度 R²（对 f_inst(t) 线性拟合）
    p    = polyfit(tm, f_inst, 1);
    f_fit = polyval(p, tm);
    SS_res = sum((f_inst - f_fit).^2);
    SS_tot = sum((f_inst - mean(f_inst)).^2);
    R2 = 1 - SS_res/(SS_tot + 1e-12);

    % 判别
    if BW_hat < BW_thresh
        label = 'CW';
    elseif R2 >= R2_thresh
        label = 'LFM';
    else
        label = 'HFM';
    end
    correct = strcmp(label, true_labels{si});
    fprintf('  %s信号：BW_hat=%.1f Hz，R²=%.4f → 判别=%s (%s)\n', ...
            sig_names{si}, BW_hat, R2, label, ...
            char('正确'*correct + '错误'*(1-correct)));
    if correct, res_str = '✓正确'; else, res_str = '✗错误'; end

    subplot(3,3,si);
    imagesc(tm, fm/1e3, 20*log10(Sm+1e-9)); axis xy; colormap jet;
    xlabel('t (s)'); ylabel('f (kHz)');
    title(sprintf('%s 时频图', sig_names{si}));
    ylim([0 fs_sim/2/1e3]);
    cb=colorbar; cb.Label.String='dB';
    clim_vals = prctile(20*log10(Sm(:)+1e-9),[5 98]);
    clim(clim_vals);

    subplot(3,3,si+3);
    plot(tm, f_inst/1e3,'b.','MarkerSize',3); hold on;
    plot(tm, f_fit/1e3, 'r-','LineWidth',1.5);
    xlabel('t (s)'); ylabel('f (kHz)');
    title(sprintf('瞬时频率 & 线性拟合（R²=%.4f）',R2));
    legend('峰值频率','线性拟合','Location','best'); grid on;

    subplot(3,3,si+6);
    bar([BW_hat, BW_thresh],'FaceColor','flat','CData',[0.3 0.6 0.9;0.9 0.3 0.3]);
    set(gca,'XTickLabel',{'BW\_hat','BW\_thresh'});
    ylabel('Hz'); title(sprintf('带宽判别 → %s  %s',label,res_str));
    text(1, BW_hat*0.5, sprintf('%.1f Hz',BW_hat),'HorizontalAlignment','center','FontWeight','bold');
end
sgtitle('§2.1 — 步骤2：类型判别（CW/LFM/HFM）','FontSize',13,'FontWeight','bold');

%% —— 组合脉冲分段判别 ——
fprintf('\n【组合脉冲分段判别】\n');
[Sc, tc, fc] = my_stft(s_combo, win_len, step_len, nfft_s, fs_sim);

% 将时频图按子脉冲时长分三段
seg_t = [0, tau_fm, 2*tau_fm, 3*tau_fm];
seg_labels = {};
for si = 1:3
    t_lo = seg_t(si);   t_hi = seg_t(si+1);
    idx_frames = tc >= t_lo & tc < t_hi;
    Sm_seg = Sc(:, idx_frames);
    tm_seg = tc(idx_frames);
    fm_seg = fc;

    [~, peak_idx] = max(Sm_seg, [], 1);
    f_inst_seg = fm_seg(peak_idx)';
    mean_spec = mean(Sm_seg, 2);
    cum_en = cumsum(mean_spec.^2) / sum(mean_spec.^2);
    f_lo_s = fm_seg(find(cum_en > 0.05, 1, 'first'));
    f_hi_s = fm_seg(find(cum_en < 0.95, 1, 'last'));
    BW_seg = f_hi_s - f_lo_s;

    p = polyfit(tm_seg, f_inst_seg, 1);
    f_fit_seg = polyval(p, tm_seg);
    SS_res = sum((f_inst_seg - f_fit_seg).^2);
    SS_tot = sum((f_inst_seg - mean(f_inst_seg)).^2);
    R2_seg = 1 - SS_res/(SS_tot + 1e-12);

    if BW_seg < BW_thresh
        lbl = 'CW';
    elseif R2_seg >= R2_thresh
        lbl = 'LFM';
    else
        lbl = 'HFM';
    end
    seg_labels{si} = lbl;
    fprintf('  子段%d（%.1f~%.1f s）：BW=%.1f Hz，R²=%.4f → %s\n', ...
            si, t_lo, t_hi, BW_seg, R2_seg, lbl);
end
fprintf('  组合脉冲判别结果：%s-%s-%s（真值：LFM-CW-HFM）\n', ...
        seg_labels{1}, seg_labels{2}, seg_labels{3});

figure('Name','2.1 组合脉冲判别','Position',[80 80 1000 400]);
imagesc(tc, fc/1e3, 20*log10(Sc+1e-9)); axis xy; colormap jet;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title('§2.1 — 组合脉冲时频图（分段判别结果）');
ylim([0 fs_sim/2/1e3]);
cb=colorbar; cb.Label.String='dB';
clim_vals = prctile(20*log10(Sc(:)+1e-9),[5 98]); clim(clim_vals);
for si = 1:3
    xline(seg_t(si+1),'w--','LineWidth',1.5);
    text(seg_t(si)+tau_fm*0.5, fs_sim/2/1e3*0.92, ...
         seg_labels{si},'Color','w','FontSize',13,'FontWeight','bold', ...
         'HorizontalAlignment','center');
end

%% ============================================================
%  §2.2  CW 脉冲信号频率估计（s.mat 与 x.mat）
%% ============================================================

fprintf('\n\n========== §2.2 CW 脉冲信号频率估计 ==========\n\n');

%% —— 读取数据 ——
data_s = load('s.mat');  s_sig = data_s.s(:);
data_x = load('x.mat');  x_sig = data_x.x(:);
fs_cw = 20000;   % Hz
N_cw  = length(s_sig);
T_cw  = N_cw / fs_cw;   % 50 s
df    = fs_cw / N_cw;    % 频率分辨率

fprintf('信号长度 N = %d，采样率 fs = %d Hz，时长 = %.1f s\n', N_cw, fs_cw, T_cw);
fprintf('频率分辨率 Δf = fs/N = %d/%d = %.6f Hz\n\n', fs_cw, N_cw, df);

%% —— FFT 与幅度谱 ——
S_fft = fft(s_sig, N_cw);
X_fft = fft(x_sig, N_cw);
f_ax  = (0:N_cw/2) * fs_cw / N_cw;   % 单边频率轴

% 单边幅度谱（归一化）
As = abs(S_fft(1:N_cw/2+1)) * 2 / N_cw;
Ax = abs(X_fft(1:N_cw/2+1)) * 2 / N_cw;

% 峰值频率
[As_max, idx_s] = max(As);
[Ax_max, idx_x] = max(Ax);
f_peak_s = f_ax(idx_s);
f_peak_x = f_ax(idx_x);

%% —— 频率精细估计：重心法（质心插值）——
%   利用峰值附近三点频谱幅度进行重心插值，提高频率估计精度至亚分辨率
%
%   f_est = ( f_{k-1}·|S_{k-1}| + f_k·|S_k| + f_{k+1}·|S_{k+1}| )
%           / ( |S_{k-1}| + |S_k| + |S_{k+1}| )
%
%   适用条件：信号为单频正弦，且峰值周围无其他强分量

% 纯信号 s
w = 10;   % 峰值附近搜索宽度（频率箱数）
idx_s_lo = max(1, idx_s-w);   idx_s_hi = min(length(f_ax), idx_s+w);
A_win_s  = As(idx_s_lo:idx_s_hi);
f_win_s  = f_ax(idx_s_lo:idx_s_hi);
f_cog_s  = sum(f_win_s .* A_win_s) / sum(A_win_s);   % 重心频率

% 含噪信号 x
idx_x_lo = max(1, idx_x-w);   idx_x_hi = min(length(f_ax), idx_x+w);
A_win_x  = Ax(idx_x_lo:idx_x_hi);
f_win_x  = f_ax(idx_x_lo:idx_x_hi);
f_cog_x  = sum(f_win_x .* A_win_x) / sum(A_win_x);

fprintf('【频率初测（峰值法）】\n');
fprintf('  纯信号 s：峰值频率 = %.4f Hz（频率箱 #%d）\n', f_peak_s, idx_s-1);
fprintf('  含噪信号 x：峰值频率 = %.4f Hz（频率箱 #%d）\n\n', f_peak_x, idx_x-1);

fprintf('【频率精估（重心插值法）】\n');
fprintf('  纯信号 s：f_est = %.6f Hz\n', f_cog_s);
fprintf('  含噪信号 x：f_est = %.6f Hz\n\n', f_cog_x);

fprintf('【误差分析】\n');
fprintf('  峰值法误差上界：Δf/2 = %.6f Hz\n', df/2);
fprintf('  s 重心插值与峰值法差异：%.6f Hz\n', abs(f_cog_s - f_peak_s));
fprintf('  x 重心插值与峰值法差异：%.6f Hz\n', abs(f_cog_x - f_peak_x));

%% —— 功率谱密度估计（Welch法，含噪信号对比）——
seg_len_w = round(fs_cw * 2);   % 2 s 分段
[Pxx_s, f_welch] = pwelch(s_sig, hann(seg_len_w), seg_len_w/2, seg_len_w, fs_cw);
[Pxx_x, ~]       = pwelch(x_sig, hann(seg_len_w), seg_len_w/2, seg_len_w, fs_cw);
[~, idx_ws] = max(Pxx_s);   [~, idx_wx] = max(Pxx_x);
fprintf('【Welch功率谱峰值频率】\n');
fprintf('  纯信号 s：%.4f Hz\n', f_welch(idx_ws));
fprintf('  含噪信号 x：%.4f Hz\n\n', f_welch(idx_wx));

%% —— 图1：幅度谱全貌对比 ——
figure('Name','2.2 幅度谱全貌','Position',[80 80 1300 600]);

subplot(2,1,1);
plot(f_ax/1e3, 20*log10(As+1e-12), 'b', 'LineWidth', 0.8);
xlabel('频率 f (kHz)'); ylabel('幅度谱 (dB)');
title(sprintf('纯信号 s — 单边幅度谱（N=%d，Δf=%.4f Hz）', N_cw, df));
xlim([0 fs_cw/2/1e3]); grid on;
xline(f_peak_s/1e3,'r--',sprintf('峰值 %.4f Hz',f_peak_s),...
      'LabelVerticalAlignment','bottom','LineWidth',1.5);

subplot(2,1,2);
plot(f_ax/1e3, 20*log10(Ax+1e-12), 'Color',[0.7 0.1 0.1], 'LineWidth', 0.8);
xlabel('频率 f (kHz)'); ylabel('幅度谱 (dB)');
title(sprintf('含噪信号 x — 单边幅度谱（SNR≈−3 dB）'));
xlim([0 fs_cw/2/1e3]); grid on;
xline(f_peak_x/1e3,'b--',sprintf('峰值 %.4f Hz',f_peak_x),...
      'LabelVerticalAlignment','bottom','LineWidth',1.5);

sgtitle('§2.2 — CW信号幅度谱（全貌）','FontSize',13,'FontWeight','bold');

%% —— 图2：峰值区域放大 + 重心法标注 ——
% 显示峰值附近 ±5 Hz 范围
zoom_bw = 5;   % Hz
idx_zoom_s = f_ax >= (f_peak_s-zoom_bw) & f_ax <= (f_peak_s+zoom_bw);
idx_zoom_x = f_ax >= (f_peak_x-zoom_bw) & f_ax <= (f_peak_x+zoom_bw);

figure('Name','2.2 峰值区域放大','Position',[80 80 1300 700]);

subplot(2,2,1);
stem(f_ax(idx_zoom_s), As(idx_zoom_s), 'b', 'MarkerSize', 4, 'LineWidth', 1.2);
hold on;
xline(f_peak_s, 'r--', sprintf('峰值法\n%.4f Hz', f_peak_s), ...
      'LabelVerticalAlignment','bottom','LineWidth',1.5);
xline(f_cog_s,  'g-.', sprintf('重心法\n%.4f Hz', f_cog_s),  ...
      'LabelVerticalAlignment','top','LineWidth',1.5);
xlabel('频率 f (Hz)'); ylabel('幅度');
title('纯信号 s — 峰值区域放大（±5 Hz）');
grid on; legend('幅度谱','峰值法','重心法','Location','northwest');

subplot(2,2,2);
stem(f_ax(idx_zoom_x), Ax(idx_zoom_x), 'Color',[0.7 0.1 0.1], ...
     'MarkerSize',4,'LineWidth',1.2);
hold on;
xline(f_peak_x,'r--',sprintf('峰值法\n%.4f Hz',f_peak_x),...
      'LabelVerticalAlignment','bottom','LineWidth',1.5);
xline(f_cog_x, 'g-.',sprintf('重心法\n%.4f Hz',f_cog_x),...
      'LabelVerticalAlignment','top','LineWidth',1.5);
xlabel('频率 f (Hz)'); ylabel('幅度');
title('含噪信号 x — 峰值区域放大（±5 Hz）');
grid on; legend('幅度谱','峰值法','重心法','Location','northwest');

% Welch PSD
subplot(2,2,3);
idx_zoom_ws = f_welch >= (f_welch(idx_ws)-zoom_bw) & f_welch <= (f_welch(idx_ws)+zoom_bw);
plot(f_welch(idx_zoom_ws), 10*log10(Pxx_s(idx_zoom_ws)+1e-30), 'b', 'LineWidth', 1.5);
xlabel('频率 f (Hz)'); ylabel('PSD (dB/Hz)');
title(sprintf('纯信号 s — Welch PSD（峰值 %.4f Hz）', f_welch(idx_ws)));
xline(f_welch(idx_ws),'r--','LineWidth',1.5); grid on;

subplot(2,2,4);
idx_zoom_wx = f_welch >= (f_welch(idx_wx)-zoom_bw) & f_welch <= (f_welch(idx_wx)+zoom_bw);
plot(f_welch(idx_zoom_wx), 10*log10(Pxx_x(idx_zoom_wx)+1e-30), ...
     'Color',[0.7 0.1 0.1], 'LineWidth', 1.5);
xlabel('频率 f (Hz)'); ylabel('PSD (dB/Hz)');
title(sprintf('含噪信号 x — Welch PSD（峰值 %.4f Hz）', f_welch(idx_wx)));
xline(f_welch(idx_wx),'r--','LineWidth',1.5); grid on;

sgtitle('§2.2 — 峰值区域放大 & 频率估计方法对比','FontSize',13,'FontWeight','bold');

%% —— 图3：频率估计方法示意图 ——
figure('Name','2.2 测量方法示意','Position',[80 80 900 500]);
% 取峰值附近20个频率箱展示
zoom_n = 20;
idx_demo = max(1,idx_s-zoom_n):min(length(f_ax),idx_s+zoom_n);
f_demo = f_ax(idx_demo);
A_demo = As(idx_demo);

bar(f_demo, A_demo, 1, 'FaceColor',[0.4 0.6 0.9],'EdgeColor','none'); hold on;
% 重心法加权区域
bar(f_win_s, A_win_s, 1, 'FaceColor',[1 0.6 0.2],'EdgeColor','none','DisplayName','重心计算区间');
xline(f_peak_s,'r-','LineWidth',2,'DisplayName',sprintf('峰值法 f=%.4f Hz',f_peak_s));
xline(f_cog_s, 'g--','LineWidth',2,'DisplayName',sprintf('重心法 f=%.4f Hz',f_cog_s));

% 标注频率分辨率
y_arrow = As_max * 0.15;
annotation_str = sprintf('← Δf = %.4f Hz →\n（频率分辨率 = f_s/N）', df);
text(f_peak_s + df, y_arrow, annotation_str, 'Color','k','FontSize',10,...
     'HorizontalAlignment','left');

xlabel('频率 f (Hz)'); ylabel('幅度');
title({'§2.2 — 频率估计方法示意图';...
       '峰值法：取幅度最大频率箱；重心法：加权质心插值（提高精度）'});
legend('Location','northwest'); grid on;
xlim([f_peak_s-zoom_n*df, f_peak_s+zoom_n*df]);

%% —— 图4：s vs x 信号时域波形 ——
figure('Name','2.2 时域对比','Position',[80 80 1200 500]);
t_cw_ax = (0:N_cw-1)/fs_cw;
t_show = 0.01;   % 显示前 10 ms
idx_show = t_cw_ax <= t_show;

subplot(1,2,1);
plot(t_cw_ax(idx_show)*1e3, s_sig(idx_show), 'b', 'LineWidth', 1);
xlabel('时间 t (ms)'); ylabel('幅度');
title(sprintf('纯信号 s（前 %.0f ms）', t_show*1e3)); grid on;

subplot(1,2,2);
plot(t_cw_ax(idx_show)*1e3, x_sig(idx_show), 'Color',[0.7 0.1 0.1], 'LineWidth', 0.8);
xlabel('时间 t (ms)'); ylabel('幅度');
title(sprintf('含噪信号 x（前 %.0f ms，SNR≈−3 dB）', t_show*1e3)); grid on;

sgtitle('§2.2 — 纯信号 s 与含噪信号 x 时域波形（前10ms）',...
        'FontSize',12,'FontWeight','bold');

%% —— 汇总输出 ——
fprintf('========== 频率估计汇总 ==========\n');
fprintf('  方法           | 纯信号 s        | 含噪信号 x\n');
fprintf('  --------------|-----------------|----------------\n');
fprintf('  FFT峰值法      | %10.4f Hz   | %10.4f Hz\n', f_peak_s, f_peak_x);
fprintf('  重心插值法     | %10.6f Hz   | %10.6f Hz\n', f_cog_s,  f_cog_x);
fprintf('  Welch PSD峰值  | %10.4f Hz   | %10.4f Hz\n', f_welch(idx_ws), f_welch(idx_wx));
fprintf('  频率分辨率 Δf  | %10.6f Hz   | （同左）\n', df);
fprintf('\n  测量公式：f_est = k_peak × (fs/N)，其中 k_peak 为幅度谱峰值对应频率箱序号\n');
fprintf('  不确定度上界：|f_true - f_est| ≤ Δf/2 = %.6f Hz\n', df/2);
fprintf('====================================\n');

display_content.json_block:
{"language": "plaintext", "code": "%% 任务2：主动探测脉冲信号检测、类型辨识与参数估计
% 2.1 基于STFT的检测与类型判别方法设计与验证
% 2.2 CW脉冲信号频率估计（纯信号s.mat与含噪信号x.mat，fs=20kHz，SNR=-3dB）
%
% 运行前请将 s.mat 和 x.mat 放置在当前工作目录，或修改下方路径。

clear; close all; clc;

%% ============================================================
%  §2.1  脉冲信号检测与类型判别方法设计与验证
%  （基于任务1.1中仿真的三类信号进行验证）
%% ============================================================

fprintf('========== §2.1 脉冲信号检测与类型判别 ==========\n\n');

%% —— 重新生成任务1中的三类信号 ——
fs_sim = 17941;
f0     = 3980.1;   tau_cw  = 1.9;
f1_lf  = 1405.0;   f2_lf   = 2164.3;  tau_fm  = 1.7;
BW     = f2_lf - f1_lf;

t_cw  = (0:1/fs_sim:tau_cw-1/fs_sim)';
s_cw  = cos(2*pi*f0*t_cw);

t_fm  = (0:1/fs_sim:tau_fm-1/fs_sim)';
k_lfm = (f2_lf-f1_lf)/tau_fm;
s_lfm = cos(2*pi*(f1_lf*t_fm + 0.5*k_lfm*t_fm.^2));

phi_hfm = -2*pi*f1_lf*f2_lf*tau_fm/BW * log(1 - BW/(f2_lf*tau_fm)*t_fm);
s_hfm   = cos(phi_hfm);

t_sub   = t_fm;
sub_lfm = s_lfm;
sub_cw  = cos(2*pi*f0*t_sub);
sub_hfm = s_hfm;
s_combo = [sub_lfm; sub_cw; sub_hfm];
t_combo = (0:length(s_combo)-1)'/fs_sim;

% 加白噪声（SNR = 5 dB，验证检测鲁棒性）
snr_val  = 5;   % dB
noise_cw  = randn(size(s_cw))  * sqrt(mean(s_cw.^2)  / 10^(snr_val/10));
noise_combo = randn(size(s_combo)) * sqrt(mean(s_combo.^2) / 10^(snr_val/10));
s_cw_n    = s_cw    + noise_cw;
s_combo_n = s_combo + noise_combo;

%% —— STFT 辅助函数 ——
    function [Smag, t_vec, f_vec] = my_stft(x, win_len, step, nfft_pts, fs_hz)
        win     = hann(win_len);
        N       = length(x);
        n_frames = floor((N - win_len)/step) + 1;
        Smag    = zeros(floor(nfft_pts/2)+1, n_frames);
        for ki = 1:n_frames
            idx   = (ki-1)*step + (1:win_len);
            frame = x(idx) .* win;
            X     = fft(frame, nfft_pts);
            Smag(:,ki) = abs(X(1:floor(nfft_pts/2)+1));
        end
        t_vec = ((0:n_frames-1)*step + win_len/2) / fs_hz;
        f_vec = (0:floor(nfft_pts/2)) * fs_hz / nfft_pts;
    end

win_len  = round(0.05*fs_sim);   % 50 ms
step_len = round(win_len/4);
nfft_s   = 2^nextpow2(win_len*2);

%% —— 步骤1：脉冲信号检测（基于时域能量检测 + STFT 帧能量）——
%
% 原理：
%   对 STFT 每一帧计算频带内总能量 E(m)，
%   设置自适应门限 T = μ_noise + k·σ_noise（k=3~5），
%   当连续若干帧 E(m) > T 时判定为脉冲存在。
%
%   检测流程（CFAR-like）：
%   1. 对每帧 STFT 幅度谱求能量 E(m) = Σ|S(f,m)|²
%   2. 选取无信号区段（前/后静默段）估计噪声统计量 μ_noise, σ_noise
%   3. 门限 T = μ_noise + k·σ_noise
%   4. 寻找 E(m) > T 的帧段，确定起止时间 → 脉冲检测结果

% 在组合脉冲前加 0.3 s 静默（纯噪声）用于演示检测
t_silence = 0.3;
N_silence = round(t_silence * fs_sim);
noise_floor = 0.08 * randn(N_silence, 1);
s_detect = [noise_floor; s_combo_n];
t_detect = (0:length(s_detect)-1)'/fs_sim;

[E_stft, t_e, f_e] = my_stft(s_detect, win_len, step_len, nfft_s, fs_sim);
frame_energy = sum(E_stft.^2, 1)';   % 每帧总能量

% 用前若干帧（静默段）估计噪声能量统计
n_noise_frames = round(t_silence*fs_sim / step_len) - 2;
n_noise_frames = max(n_noise_frames, 5);
mu_n  = mean(frame_energy(1:n_noise_frames));
sig_n = std(frame_energy(1:n_noise_frames));
k_cfar = 4;
threshold = mu_n + k_cfar * sig_n;

detect_flag = frame_energy > threshold;   % 1=有信号

% 找脉冲起止时间
edges = diff([0; detect_flag; 0]);
t_start_det = t_e(edges(1:end-1) == 1);
t_end_det   = t_e(edges(2:end)   == -1);

fprintf('【检测结果】\n');
fprintf('  噪声帧均值 = %.2f，标准差 = %.2f，门限 T = %.2f（k=%d）\n', ...
        mu_n, sig_n, threshold, k_cfar);
for di = 1:length(t_start_det)
    fprintf('  脉冲 #%d：起始 %.3f s，终止 %.3f s，时长 %.3f s\n', ...
            di, t_start_det(di), t_end_det(di), t_end_det(di)-t_start_det(di));
end

% 绘制检测图
figure('Name','2.1 脉冲检测','Position',[80 80 1200 600]);
subplot(2,1,1);
plot(t_detect, s_detect, 'Color',[0.3 0.5 0.8], 'LineWidth',0.5);
xlabel('时间 t (s)'); ylabel('幅度');
title('待检测信号（静默段 + 组合脉冲，SNR=5 dB）');
grid on;
for di = 1:length(t_start_det)
    xregion(t_start_det(di), t_end_det(di), ...
            'FaceColor',[1 0.6 0.1], 'FaceAlpha',0.25);
end

subplot(2,1,2);
plot(t_e, frame_energy, 'b', 'LineWidth', 1); hold on;
yline(threshold, 'r--', sprintf('门限 T=%.1f（k=%d）', threshold, k_cfar), ...
      'LineWidth', 1.5);
for di = 1:length(t_start_det)
    xregion(t_start_det(di), t_end_det(di), ...
            'FaceColor',[1 0.6 0.1], 'FaceAlpha',0.25);
end
xlabel('时间 t (s)'); ylabel('帧能量 E(m)');
title('STFT 帧能量 + 自适应门限检测');
legend('帧能量','门限 T','检测区间'); grid on;
sgtitle('§2.1 — 步骤1：脉冲信号检测（CFAR-like 能量检测）', ...
        'FontSize',13,'FontWeight','bold');

%% —— 步骤2：类型判别（CW / LFM / HFM / 组合） ——
%
% 判别特征：
%   F1: 频带宽度 BW_hat = f_max_active - f_min_active
%       CW → BW ≈ 0（单频）
%       LFM/HFM → BW > 阈值
%
%   F2: 调频线性度 R²（对瞬时频率 vs 时间做线性回归）
%       LFM → R² ≈ 1（线性）
%       HFM → R² < 阈值（非线性）
%
%   F3: 多段分析（组合脉冲 → 不同子段特征不同）
%
% 判别规则（基于阈值）：
%   BW_hat < BW_thresh             → CW
%   BW_hat ≥ BW_thresh, R² ≥ R²_thresh → LFM
%   BW_hat ≥ BW_thresh, R² < R²_thresh → HFM
%   （组合脉冲需先分段再对每段分类）

fprintf('\n【类型判别】\n');

BW_thresh = 200;   % Hz，带宽判别阈值
R2_thresh  = 0.95; % 线性度判别阈值

signals   = {s_cw, s_lfm, s_hfm};
sig_names = {'CW', 'LFM', 'HFM'};
true_labels = {'CW', 'LFM', 'HFM'};

figure('Name','2.1 类型判别','Position',[80 80 1400 700]);
for si = 1:3
    sig   = signals{si};
    ts    = (0:length(sig)-1)'/fs_sim;
    [Sm, tm, fm] = my_stft(sig, win_len, step_len, nfft_s, fs_sim);

    % 每帧峰值频率（瞬时频率估计）
    [~, peak_idx] = max(Sm, [], 1);
    f_inst = fm(peak_idx)';

    % 带宽估计（5%能量边界）
    mean_spec = mean(Sm, 2);
    cum_en    = cumsum(mean_spec.^2) / sum(mean_spec.^2);
    f_lo = fm(find(cum_en > 0.05, 1, 'first'));
    f_hi = fm(find(cum_en < 0.95, 1, 'last'));
    BW_hat = f_hi - f_lo;

    % 线性度 R²（对 f_inst(t) 线性拟合）
    p    = polyfit(tm, f_inst, 1);
    f_fit = polyval(p, tm);
    SS_res = sum((f_inst - f_fit).^2);
    SS_tot = sum((f_inst - mean(f_inst)).^2);
    R2 = 1 - SS_res/(SS_tot + 1e-12);

    % 判别
    if BW_hat < BW_thresh
        label = 'CW';
    elseif R2 >= R2_thresh
        label = 'LFM';
    else
        label = 'HFM';
    end
    correct = strcmp(label, true_labels{si});
    fprintf('  %s信号：BW_hat=%.1f Hz，R²=%.4f → 判别=%s (%s)\n', ...
            sig_names{si}, BW_hat, R2, label, ...
            char('正确'*correct + '错误'*(1-correct)));
    if correct, res_str = '✓正确'; else, res_str = '✗错误'; end

    subplot(3,3,si);
    imagesc(tm, fm/1e3, 20*log10(Sm+1e-9)); axis xy; colormap jet;
    xlabel('t (s)'); ylabel('f (kHz)');
    title(sprintf('%s 时频图', sig_names{si}));
    ylim([0 fs_sim/2/1e3]);
    cb=colorbar; cb.Label.String='dB';
    clim_vals = prctile(20*log10(Sm(:)+1e-9),[5 98]);
    clim(clim_vals);

    subplot(3,3,si+3);
    plot(tm, f_inst/1e3,'b.','MarkerSize',3); hold on;
    plot(tm, f_fit/1e3, 'r-','LineWidth',1.5);
    xlabel('t (s)'); ylabel('f (kHz)');
    title(sprintf('瞬时频率 & 线性拟合（R²=%.4f）',R2));
    legend('峰值频率','线性拟合','Location','best'); grid on;

    subplot(3,3,si+6);
    bar([BW_hat, BW_thresh],'FaceColor','flat','CData',[0.3 0.6 0.9;0.9 0.3 0.3]);
    set(gca,'XTickLabel',{'BW\_hat','BW\_thresh'});
    ylabel('Hz'); title(sprintf('带宽判别 → %s  %s',label,res_str));
    text(1, BW_hat*0.5, sprintf('%.1f Hz',BW_hat),'HorizontalAlignment','center','FontWeight','bold');
end
sgtitle('§2.1 — 步骤2：类型判别（CW/LFM/HFM）','FontSize',13,'FontWeight','bold');

%% —— 组合脉冲分段判别 ——
fprintf('\n【组合脉冲分段判别】\n');
[Sc, tc, fc] = my_stft(s_combo, win_len, step_len, nfft_s, fs_sim);

% 将时频图按子脉冲时长分三段
seg_t = [0, tau_fm, 2*tau_fm, 3*tau_fm];
seg_labels = {};
for si = 1:3
    t_lo = seg_t(si);   t_hi = seg_t(si+1);
    idx_frames = tc >= t_lo & tc < t_hi;
    Sm_seg = Sc(:, idx_frames);
    tm_seg = tc(idx_frames);
    fm_seg = fc;

    [~, peak_idx] = max(Sm_seg, [], 1);
    f_inst_seg = fm_seg(peak_idx)';
    mean_spec = mean(Sm_seg, 2);
    cum_en = cumsum(mean_spec.^2) / sum(mean_spec.^2);
    f_lo_s = fm_seg(find(cum_en > 0.05, 1, 'first'));
    f_hi_s = fm_seg(find(cum_en < 0.95, 1, 'last'));
    BW_seg = f_hi_s - f_lo_s;

    p = polyfit(tm_seg, f_inst_seg, 1);
    f_fit_seg = polyval(p, tm_seg);
    SS_res = sum((f_inst_seg - f_fit_seg).^2);
    SS_tot = sum((f_inst_seg - mean(f_inst_seg)).^2);
    R2_seg = 1 - SS_res/(SS_tot + 1e-12);

    if BW_seg < BW_thresh
        lbl = 'CW';
    elseif R2_seg >= R2_thresh
        lbl = 'LFM';
    else
        lbl = 'HFM';
    end
    seg_labels{si} = lbl;
    fprintf('  子段%d（%.1f~%.1f s）：BW=%.1f Hz，R²=%.4f → %s\n', ...
            si, t_lo, t_hi, BW_seg, R2_seg, lbl);
end
fprintf('  组合脉冲判别结果：%s-%s-%s（真值：LFM-CW-HFM）\n', ...
        seg_labels{1}, seg_labels{2}, seg_labels{3});

figure('Name','2.1 组合脉冲判别','Position',[80 80 1000 400]);
imagesc(tc, fc/1e3, 20*log10(Sc+1e-9)); axis xy; colormap jet;
xlabel('时间 t (s)'); ylabel('频率 f (kHz)');
title('§2.1 — 组合脉冲时频图（分段判别结果）');
ylim([0 fs_sim/2/1e3]);
cb=colorbar; cb.Label.String='dB';
clim_vals = prctile(20*log10(Sc(:)+1e-9),[5 98]); clim(clim_vals);
for si = 1:3
    xline(seg_t(si+1),'w--','LineWidth',1.5);
    text(seg_t(si)+tau_fm*0.5, fs_sim/2/1e3*0.92, ...
         seg_labels{si},'Color','w','FontSize',13,'FontWeight','bold', ...
         'HorizontalAlignment','center');
end

%% ============================================================
%  §2.2  CW 脉冲信号频率估计（s.mat 与 x.mat）
%% ============================================================

fprintf('\n\n========== §2.2 CW 脉冲信号频率估计 ==========\n\n');

%% —— 读取数据 ——
data_s = load('s.mat');  s_sig = data_s.s(:);
data_x = load('x.mat');  x_sig = data_x.x(:);
fs_cw = 20000;   % Hz
N_cw  = length(s_sig);
T_cw  = N_cw / fs_cw;   % 50 s
df    = fs_cw / N_cw;    % 频率分辨率

fprintf('信号长度 N = %d，采样率 fs = %d Hz，时长 = %.1f s\n', N_cw, fs_cw, T_cw);
fprintf('频率分辨率 Δf = fs/N = %d/%d = %.6f Hz\n\n', fs_cw, N_cw, df);

%% —— FFT 与幅度谱 ——
S_fft = fft(s_sig, N_cw);
X_fft = fft(x_sig, N_cw);
f_ax  = (0:N_cw/2) * fs_cw / N_cw;   % 单边频率轴

% 单边幅度谱（归一化）
As = abs(S_fft(1:N_cw/2+1)) * 2 / N_cw;
Ax = abs(X_fft(1:N_cw/2+1)) * 2 / N_cw;

% 峰值频率
[As_max, idx_s] = max(As);
[Ax_max, idx_x] = max(Ax);
f_peak_s = f_ax(idx_s);
f_peak_x = f_ax(idx_x);

%% —— 频率精细估计：重心法（质心插值）——
%   利用峰值附近三点频谱幅度进行重心插值，提高频率估计精度至亚分辨率
%
%   f_est = ( f_{k-1}·|S_{k-1}| + f_k·|S_k| + f_{k+1}·|S_{k+1}| )
%           / ( |S_{k-1}| + |S_k| + |S_{k+1}| )
%
%   适用条件：信号为单频正弦，且峰值周围无其他强分量

% 纯信号 s
w = 10;   % 峰值附近搜索宽度（频率箱数）
idx_s_lo = max(1, idx_s-w);   idx_s_hi = min(length(f_ax), idx_s+w);
A_win_s  = As(idx_s_lo:idx_s_hi);
f_win_s  = f_ax(idx_s_lo:idx_s_hi);
f_cog_s  = sum(f_win_s .* A_win_s) / sum(A_win_s);   % 重心频率

% 含噪信号 x
idx_x_lo = max(1, idx_x-w);   idx_x_hi = min(length(f_ax), idx_x+w);
A_win_x  = Ax(idx_x_lo:idx_x_hi);
f_win_x  = f_ax(idx_x_lo:idx_x_hi);
f_cog_x  = sum(f_win_x .* A_win_x) / sum(A_win_x);

fprintf('【频率初测（峰值法）】\n');
fprintf('  纯信号 s：峰值频率 = %.4f Hz（频率箱 #%d）\n', f_peak_s, idx_s-1);
fprintf('  含噪信号 x：峰值频率 = %.4f Hz（频率箱 #%d）\n\n', f_peak_x, idx_x-1);

fprintf('【频率精估（重心插值法）】\n');
fprintf('  纯信号 s：f_est = %.6f Hz\n', f_cog_s);
fprintf('  含噪信号 x：f_est = %.6f Hz\n\n', f_cog_x);

fprintf('【误差分析】\n');
fprintf('  峰值法误差上界：Δf/2 = %.6f Hz\n', df/2);
fprintf('  s 重心插值与峰值法差异：%.6f Hz\n', abs(f_cog_s - f_peak_s));
fprintf('  x 重心插值与峰值法差异：%.6f Hz\n', abs(f_cog_x - f_peak_x));

%% —— 功率谱密度估计（Welch法，含噪信号对比）——
seg_len_w = round(fs_cw * 2);   % 2 s 分段
[Pxx_s, f_welch] = pwelch(s_sig, hann(seg_len_w), seg_len_w/2, seg_len_w, fs_cw);
[Pxx_x, ~]       = pwelch(x_sig, hann(seg_len_w), seg_len_w/2, seg_len_w, fs_cw);
[~, idx_ws] = max(Pxx_s);   [~, idx_wx] = max(Pxx_x);
fprintf('【Welch功率谱峰值频率】\n');
fprintf('  纯信号 s：%.4f Hz\n', f_welch(idx_ws));
fprintf('  含噪信号 x：%.4f Hz\n\n', f_welch(idx_wx));

%% —— 图1：幅度谱全貌对比 ——
figure('Name','2.2 幅度谱全貌','Position',[80 80 1300 600]);

subplot(2,1,1);
plot(f_ax/1e3, 20*log10(As+1e-12), 'b', 'LineWidth', 0.8);
xlabel('频率 f (kHz)'); ylabel('幅度谱 (dB)');
