```matlab
%% 主动探测脉冲接收信号短时窗检测仿真
clear; clc; close all;

%% 1. 参数设置
fs = 32000;         % 采样率 Hz
t_start = 0.2;      % 脉冲起始时间 s
t_zero = 0.2;       % 脉冲结束后零值时长 s

% LFM 参数
f1 = 2900; f2 = 3700;
T_LFM = 2;          % LFM 脉宽 s

% CW 参数
f0 = 3300;
T_CW = 1;           % CW 脉宽 s

% 噪声参数（全频带 SNR = 0 dB）
SNR_dB = 0;
A = 1;              % 信号幅度
sigma = A / sqrt(2 * 10^(SNR_dB/10));  % 噪声标准差

%% 2. 生成信号

% --- LFM 信号 ---
t_LFM_total = t_start + T_LFM + t_zero;
t_LFM = (0 : 1/fs : t_LFM_total - 1/fs);
N_LFM = length(t_LFM);

sig_LFM = zeros(1, N_LFM);
idx_LFM = (t_LFM >= t_start) & (t_LFM < t_start + T_LFM);
t_pulse_LFM = t_LFM(idx_LFM) - t_start;
sig_LFM(idx_LFM) = A * cos(2*pi*(f1*t_pulse_LFM + (f2-f1)/(2*T_LFM)*t_pulse_LFM.^2));

noise_LFM = sigma * randn(1, N_LFM);
rx_LFM = sig_LFM + noise_LFM;

% --- CW 信号 ---
t_CW_total = t_start + T_CW + t_zero;
t_CW = (0 : 1/fs : t_CW_total - 1/fs);
N_CW = length(t_CW);

sig_CW = zeros(1, N_CW);
idx_CW = (t_CW >= t_start) & (t_CW < t_start + T_CW);
t_pulse_CW = t_CW(idx_CW) - t_start;
sig_CW(idx_CW) = A * cos(2*pi*f0*t_pulse_CW);

noise_CW = sigma * randn(1, N_CW);
rx_CW = sig_CW + noise_CW;

% --- 组合脉冲信号（LFM + CW，顺序拼接）---
% LFM在前，CW紧随其后（共享起始零值），中间无间隔
t_combo_total = t_start + T_LFM + T_CW + t_zero;
t_combo = (0 : 1/fs : t_combo_total - 1/fs);
N_combo = length(t_combo);

sig_combo = zeros(1, N_combo);
idx_combo_LFM = (t_combo >= t_start) & (t_combo < t_start + T_LFM);
idx_combo_CW  = (t_combo >= t_start + T_LFM) & (t_combo < t_start + T_LFM + T_CW);

t_p_LFM = t_combo(idx_combo_LFM) - t_start;
t_p_CW  = t_combo(idx_combo_CW)  - (t_start + T_LFM);

sig_combo(idx_combo_LFM) = A * cos(2*pi*(f1*t_p_LFM + (f2-f1)/(2*T_LFM)*t_p_LFM.^2));
sig_combo(idx_combo_CW)  = A * cos(2*pi*f0*t_p_CW);

noise_combo = sigma * randn(1, N_combo);
rx_combo = sig_combo + noise_combo;

%% 3. STFT 短时窗检测函数
% 参数
M    = 2048;        % 窗长（约 64ms @ 32kHz）
STEP = M / 2;       % 步进（1/2 窗长）
gamma = 10;         % 检测门限（SNR 线性值）

% 检测频带
f_low  = 900;
f_high = 5000;
k_l = round(f_low  / fs * M) + 1;   % MATLAB 下标从1开始
k_h = round(f_high / fs * M) + 1;

fprintf('检测频带下标: k_l=%d (%.0fHz), k_h=%d (%.0fHz)\n', ...
    k_l, (k_l-1)*fs/M, k_h, (k_h-1)*fs/M);

%% 4. 对三种信号分别进行检测
signals  = {rx_LFM, rx_CW, rx_combo};
t_axes   = {t_LFM,  t_CW,  t_combo};
sig_names = {'LFM 脉冲', 'CW 脉冲', '组合脉冲 (LFM+CW)'};

for s = 1 : 3
    rx = signals{s};
    t  = t_axes{s};
    L  = length(rx);

    % 分帧数
    I = fix((L - M + STEP) / STEP);
    fprintf('\n[%s] 信号长度L=%d, 帧数I=%d\n', sig_names{s}, L, I);

    % 初始化结果向量
    km_vec  = zeros(1, I);
    Tm_vec  = zeros(1, I);
    SNR_vec = zeros(1, I);
    t_frame = zeros(1, I);  % 每帧中心时刻

    win = hanning(M)';      % 汉宁窗

    for i = 1 : I
        % 步骤2：取帧并做 FFT
        idx_start = (i-1)*STEP + 1;
        idx_end   = idx_start + M - 1;
        if idx_end > L
            break;
        end
        frame = rx(idx_start : idx_end) .* win;
        t_frame(i) = t(idx_start + M/2 - 1);   % 帧中心时刻

        Xi = fft(frame, M);
        Xi = Xi(1 : M/2);   % 单边谱

        % 步骤3：功率谱估计
        Ti = abs(Xi).^2 / M;

        % 步骤4：在检测频带内搜索最大值
        Ti_band = Ti(k_l : k_h);
        [Ti_max, km_local] = max(Ti_band);
        km = km_local + k_l - 1;    % 全局下标

        % 步骤5：带内平均功率（去除最大值周围5个频点）
        k_excl = max(k_l, km-2) : min(k_h, km+2);
        sum_band = sum(Ti(k_l:k_h));
        sum_excl = sum(Ti(k_excl));
        n_remain = (k_h - k_l + 1) - length(k_excl);
        if n_remain > 0
            Pim = (sum_band - sum_excl) / n_remain;
        else
            Pim = eps;
        end

        % 步骤6：SNR 检验
        SNRi = Ti_max / Pim;
        if SNRi > gamma
            km_vec(i)  = km;
            Tm_vec(i)  = Ti_max;
            SNR_vec(i) = SNRi;
        else
            km_vec(i)  = 0;
            Tm_vec(i)  = 0;
            SNR_vec(i) = 0;
        end
    end

    % 截断到实际帧数
    t_frame = t_frame(1:I);

    % 将下标转换为频率
    freq_vec = (km_vec - 1) * fs / M;
    freq_vec(km_vec == 0) = NaN;
    Tm_plot  = Tm_vec;  Tm_plot(Tm_vec == 0)  = NaN;
    SNR_plot = SNR_vec; SNR_plot(SNR_vec == 0) = NaN;

    %% 5. 绘图
    figure('Name', sig_names{s}, 'NumberTitle', 'off', 'Position', [100 100 900 700]);
    sgtitle(sig_names{s}, 'FontSize', 14, 'FontWeight', 'bold');

    % 子图1：接收信号时域
    subplot(4,1,1);
    plot(t, rx, 'Color', [0.4 0.6 0.9], 'LineWidth', 0.5);
    xlabel('时间 (s)'); ylabel('幅度');
    title('接收信号（含噪声）'); grid on;

    % 子图2：检测频率
    subplot(4,1,2);
    plot(t_frame, freq_vec, '.-', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', [0.2 0.7 0.3]);
    xlabel('时间 (s)'); ylabel('频率 (Hz)');
    title('逐帧检测最大值频率 k_m(i)');
    ylim([500 6000]); grid on;
    yline(f1, '--r', sprintf('f1=%dHz', f1), 'LabelVerticalAlignment', 'bottom');
    yline(f2, '--b', sprintf('f2=%dHz', f2), 'LabelVerticalAlignment', 'top');
    if s == 2 || s == 3
        yline(f0, '--m', sprintf('f0=%dHz', f0));
    end

    % 子图3：最大功率值
    subplot(4,1,3);
    plot(t_frame, 10*log10(Tm_plot+eps), '.-', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', [0.85 0.5 0.1]);
    xlabel('时间 (s)'); ylabel('功率 (dB)');
    title('逐帧最大功率值 T_m(i)'); grid on;

    % 子图4：SNR
    subplot(4,1,4);
    plot(t_frame, 10*log10(SNR_plot+eps), '.-', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', [0.7 0.2 0.5]);
    xlabel('时间 (s)'); ylabel('SNR (dB)');
    title('逐帧信噪比 SNR(i)');
    yline(10*log10(gamma), '--k', sprintf('门限 %.1fdB', 10*log10(gamma)));
    grid on;
end
