    plot(t_frame, 10*log10(Tm_plot+eps), '.-', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', [0.85 0.5 0.1]);
    xlabel('时间 (s)'); ylabel('功率 (dB)');
    title('逐帧最大功率值 T_m(i)'); grid on;

    % 子图4：SNR
    subplot(4,1,4);
    plot(t_frame, 10*log10(SNR_plot+eps), '.-', 'MarkerSize', 8, 'LineWidth', 1.2, 'Color', [0.7 0.2 0.5]);
    xlabel('时间 (s)'); ylabel('SNR (dB)');
    title('逐帧信噪比 SNR(i)');
    yline(10*log10(gamma), '--k', sprintf('门限 %.1fdB', 10*log10(gamma)));
