%% 舰船辐射噪声宽带谱分量模拟及功率谱分析
% 参数说明：
%   - 1kHz处谱级: 122 dB re 1uPa^2/Hz
%   - 线谱频率: 122 Hz, SNR = 12 dB (3条，此处取同频率叠加)
%   - 轴频: 2.5 Hz, 调制指数奇次=0.12, 偶次=0.07
%   - 采样频率: 32 kHz, 时长 >= 30 s

clear; clc; close all;

%% ========== 基本参数设置 ==========
fs      = 32000;          % 采样频率 (Hz)
T       = 30;             % 信号时长 (s)
N_total = T * fs;         % 总采样点数
t       = (0:N_total-1) / fs;  % 时间向量

p0      = 1e-6;           % 参考声压 1 μPa
rho     = 1000;           % 水密度 kg/m^3
c       = 1500;           % 声速 m/s
I0      = 6.8e-19;        % 参考声强 W/m^2

SL_1k_target = 122;       % 1kHz处目标谱级 (dB re 1μPa^2/Hz)

%% ========== Step 1: 构造目标功率谱曲线 (频率分辨率1Hz，单边谱) ==========
% 频率向量: 1 Hz 到 fs/2
f_vec = (1 : fs/2)';      % 列向量，长度 = 16000

% 谱形定义 (dB):
%   f <= 200 Hz : 平坦，144 dB
%   f >  200 Hz : 每倍频程衰减 6 dB，即 -20 dB/decade
%                 SL(f) = 144 - 20*log10(f/200)  [dB]
SL_dB = zeros(size(f_vec));
SL_dB(f_vec <= 200) = 144;
SL_dB(f_vec >  200) = 144 - 20 * log10(f_vec(f_vec > 200) / 200);

%% ========== Step 2: dB → 线性功率谱密度 (Pa^2/Hz) ==========
% SL = 10*log10(P / p0^2)  =>  P = p0^2 * 10^(SL/10)
P_target = (p0^2) .* 10.^(SL_dB / 10);  % Pa^2/Hz

%% ========== Step 3: 归一化幅频响应 ==========
H_norm = sqrt(P_target / max(P_target));

%% ========== Step 4: 设计 FIR 滤波器 (fir2, 1024阶) ==========
fir_order = 1024;

% fir2 需要归一化频率 [0,1]，0对应DC，1对应 fs/2
% f_vec 范围是 1~16000 Hz，加上 DC(0Hz) 端点和 Nyquist 端点
f_norm = [0; f_vec / (fs/2)];   % 在0处补1个点
H_norm_full = [H_norm(1); H_norm]; % DC处幅度与最低频相同

% 确保 f_norm 末端精确等于1（Nyquist）
f_norm(end) = 1;

