rng(42);  % 固定随机种子，便于复现
white_noise = randn(N_total, 1);       % 零均值单位方差
x_raw = filter(b, 1, white_noise);    % FIR滤波

%% ========== Step 6 & 7: 估计当前1kHz处谱级 ==========
% 使用 pwelch 估计功率谱密度
nfft_pwelch = fs;          % FFT点数=fs → 频率分辨率1Hz
[Pxx_raw, f_pwelch] = pwelch(x_raw, hann(nfft_pwelch), nfft_pwelch/2, nfft_pwelch, fs);

% 找1kHz附近的谱级
[~, idx_1k] = min(abs(f_pwelch - 1000));
P_1k_raw = Pxx_raw(idx_1k);

SL_raw = 10 * log10(P_1k_raw / p0^2);
fprintf('当前1kHz处谱级: %.2f dB\n', SL_raw);

%% ========== Step 8 & 9: 增益校正，得到最终宽带噪声信号 ==========
G = 10^((SL_1k_target - SL_raw) / 20);
x_broad = G * x_raw;
fprintf('增益因子 G = %.4f\n', G);

% 校正后验证1kHz谱级
[Pxx_broad, ~] = pwelch(x_broad, hann(nfft_pwelch), nfft_pwelch/2, nfft_pwelch, fs);
