semilogx(f_vec, SL_dB, 'b-', 'LineWidth', 1.5);
xlabel('频率 (Hz)'); ylabel('谱级 (dB re 1μPa^2/Hz)');
title('目标宽带辐射噪声谱形');
grid on; xlim([1 fs/2]); ylim([80 160]);
xline(200,'--r','200Hz'); xline(1000,'--g','1kHz');
yline(122,'--m','122dB');

%% ========== 图2: 宽带噪声信号波形 ==========
figure('Name','宽带噪声波形','Position',[100 150 1000 350]);
plot(t, x_broad, 'b', 'LineWidth', 0.5);
xlabel('时间 (s)'); ylabel('声压 (Pa)');
title('宽带辐射噪声信号波形');
grid on; xlim([0 T]);

%% ========== 周期图功率谱估计 (分帧) ==========
% --- 函数：单次及平均周期图 ---
% 输入: signal, fs, frame_len(s)
% 输出: 单次帧功率谱, 多帧平均功率谱, 频率向量

function [SL_single, SL_avg, f_out] = periodogram_analysis(signal, fs, frame_len_s, p0)
    frame_len = round(frame_len_s * fs);  % 帧长(点数)
    N_sig     = length(signal);
    N_frames  = floor(N_sig / frame_len); % 完整帧数

    nfft = frame_len;
    dt   = 1/fs;

    P_all = zeros(nfft/2+1, N_frames);

    for k = 1:N_frames
        seg = signal((k-1)*frame_len + 1 : k*frame_len);
        % 周期图公式: P(f) = (dt/N)|FFT(x)|^2
        X   = fft(seg, nfft);
        P_k = (dt / nfft) * abs(X).^2;
        % 单边谱 (正频率部分)，非DC非Nyquist乘2
        P_one = P_k(1:nfft/2+1);
        P_one(2:end-1) = 2 * P_one(2:end-1);
        P_all(:,k) = P_one;
    end

    % 转为谱级 (dB re 1μPa^2/Hz)
    P_single = P_all(:,1);   % 取第1帧作为单次示例
    P_avg    = mean(P_all, 2);

    f_out     = (0:nfft/2)' * (fs/nfft);
    SL_single = 10 * log10(P_single / p0^2);
    SL_avg    = 10 * log10(P_avg    / p0^2);
end

%% ========== 图3 & 4: 帧长1s的周期图 ==========
frame_len_1s = 1;  % 秒
[SL_single_1s, SL_avg_1s, f_1s] = periodogram_analysis(x_broad, fs, frame_len_1s, p0);

figure('Name','周期图 - 帧长1s','Position',[100 100 1100 450]);
