subplot(1,2,2);
semilogx(f_1s(2:end), SL_avg_1s(2:end), 'r', 'LineWidth', 1.5);
xlabel('频率 (Hz)'); ylabel('谱级 (dB re 1μPa^2/Hz)');
title('多次平均周期图功率谱估计 (帧长1s)');
grid on; xlim([1 fs/2]); ylim([60 170]);
xline(200,'--r'); xline(1000,'--g'); yline(122,'--m','122dB');

