frame_len_2s = 2;  % 秒
[SL_single_2s, SL_avg_2s, f_2s] = periodogram_analysis(x_broad, fs, frame_len_2s, p0);

figure('Name','周期图 - 帧长2s','Position',[100 100 1100 450]);
subplot(1,2,1);
semilogx(f_2s(2:end), SL_single_2s(2:end), 'b', 'LineWidth', 1);
xlabel('频率 (Hz)'); ylabel('谱级 (dB re 1μPa^2/Hz)');
title('单次周期图功率谱估计 (帧长2s)');
grid on; xlim([1 fs/2]); ylim([60 170]);
xline(200,'--r'); xline(1000,'--g'); yline(122,'--m','122dB');

subplot(1,2,2);
semilogx(f_2s(2:end), SL_avg_2s(2:end), 'r', 'LineWidth', 1.5);
xlabel('频率 (Hz)'); ylabel('谱级 (dB re 1μPa^2/Hz)');
title('多次平均周期图功率谱估计 (帧长2s)');
grid on; xlim([1 fs/2]); ylim([60 170]);
xline(200,'--r'); xline(1000,'--g'); yline(122,'--m','122dB');

%% ========== 打印分析摘要 ==========
fprintf('\n===== 功率谱估计分析摘要 =====\n');
