[~,i1k_2s] = min(abs(f_2s - 1000));
fprintf('帧长1s - 单次1kHz谱级: %.1f dB | 平均1kHz谱级: %.1f dB\n', ...
    SL_single_1s(i1k_1s), SL_avg_1s(i1k_1s));
fprintf('帧长2s - 单次1kHz谱级: %.1f dB | 平均1kHz谱级: %.1f dB\n', ...
    SL_single_2s(i1k_2s), SL_avg_2s(i1k_2s));
