% 按公式: P(f) = (dt/N)|FFT(x)|^2，单边谱
compute_periodogram = @(seg, fs) deal( ...
    (1/fs/length(seg)) * ...
    [abs(fft(seg,length(seg))).^2 * [1; 2*ones(length(seg)/2-1,1); 1]], ...
    (0:length(seg)/2)' * (fs/length(seg)) );

function [SL_single, SL_avg, f_out] = frame_periodogram(signal, fs, frame_sec, p0)
    frame_len = round(frame_sec * fs);
    N_sig     = length(signal);
    N_frames  = floor(N_sig / frame_len);
    nfft      = frame_len;
    dt        = 1 / fs;

    P_all = zeros(nfft/2 + 1, N_frames);
    for k = 1:N_frames
        seg  = signal((k-1)*frame_len + 1 : k*frame_len);
        X    = fft(seg, nfft);
        Pk   = (dt / nfft) * abs(X).^2;
        Pone = Pk(1:nfft/2+1);
        Pone(2:end-1) = 2 * Pone(2:end-1);  % 单边谱补偿
        P_all(:, k)   = Pone;
    end

    f_out     = (0:nfft/2)' * (fs / nfft);
    SL_single = 10 * log10(P_all(:,1) / p0^2);       % 第1帧
    SL_avg    = 10 * log10(mean(P_all,2) / p0^2);    % 多帧平均
end

