 ```matlab
%% 舰船辐射噪声信号仿真 - Task 1 & Task 2
% Task 1: 宽带谱分量模拟及周期图功率谱分析
% Task 2: 线谱分量叠加及功率谱分析
% 参数: 1kHz谱级=122dB, 线谱频率=122Hz, SNR=12dB(3条), fs=32kHz, T=30s

clear; clc; close all;

%% ==================== 基本参数 ====================
fs           = 32000;          % 采样频率 Hz
T            = 30;             % 信号时长 s
N_total      = T * fs;         % 总采样点数
t            = (0:N_total-1)' / fs;  % 时间向量(列)

p0           = 1e-6;           % 参考声压 1 μPa
rho          = 1000;           % 水密度 kg/m^3
c            = 1500;           % 声速 m/s

SL_1k_target = 122;            % 1kHz目标谱级 dB re 1μPa^2/Hz

% 线谱参数
f_line       = [122, 122, 122]; % 三条线谱频率 Hz（同频率）
SNR_line     = [12, 12, 12];    % 各线谱SNR (dB)

%% ==================== Task 1: Step 1 — 构造目标功率谱(dB) ====================
% 频率向量：1Hz ~ fs/2，分辨率1Hz
f_vec = (1 : fs/2)';           % 列向量，长16000

% 谱形：f<=200Hz 平坦144dB；f>200Hz 每倍频程衰减6dB(-20dB/decade)
% 注：图3-1纵坐标基准144dB为连续谱基础谱级
% 1kHz处目标谱级122dB由增益校正保证，谱形形状保持一致
SL_dB = zeros(size(f_vec));
SL_dB(f_vec <= 200) = 144;
SL_dB(f_vec >  200) = 144 - 20 * log10(f_vec(f_vec > 200) / 200);

%% Task 1: Step 2 — dB转线性功率谱密度 Pa^2/Hz
P_target = (p0^2) .* 10.^(SL_dB / 10);

%% Task 1: Step 3 — 归一化幅频响应
H_norm = sqrt(P_target / max(P_target));

%% Task 1: Step 4 — 设计FIR滤波器(fir2, 1024阶)
fir_order = 1024;

% fir2需要归一化频率[0,1]，DC端点补齐
f_norm      = [0;          f_vec / (fs/2)];
H_norm_full = [H_norm(1);  H_norm        ];
f_norm(end) = 1;  % 确保Nyquist端点精确为1

b = fir2(fir_order, f_norm, H_norm_full);
fprintf('FIR滤波器设计完成，阶数: %d\n', fir_order);

%% Task 1: Step 5 — 白噪声通过FIR滤波器
rng(42);
white_noise = randn(N_total, 1);
x_raw       = filter(b, 1, white_noise);

%% Task 1: Step 6~7 — pwelch估计当前1kHz谱级
nfft_pwelch       = fs;   % 频率分辨率1Hz
[Pxx_raw, f_pw]   = pwelch(x_raw, hann(nfft_pwelch), nfft_pwelch/2, nfft_pwelch, fs);
[~, idx_1k]       = min(abs(f_pw - 1000));
P_1k_raw          = Pxx_raw(idx_1k);
SL_raw            = 10 * log10(P_1k_raw / p0^2);
fprintf('校正前 1kHz 谱级: %.2f dB\n', SL_raw);

%% Task 1: Step 8~9 — 增益校正，得最终宽带噪声
G        = 10^((SL_1k_target - SL_raw) / 20);
x_broad  = G * x_raw;
fprintf('增益因子 G = %.4f\n', G);

% 验证
[Pxx_broad, ~] = pwelch(x_broad, hann(nfft_pwelch), nfft_pwelch/2, nfft_pwelch, fs);
SL_check       = 10 * log10(Pxx_broad(idx_1k) / p0^2);
fprintf('校正后 1kHz 谱级: %.2f dB  (目标: %d dB)\n', SL_check, SL_1k_target);

%% ==================== Task 2: 线谱生成与叠加 ====================
% Step 2-1: 获取各线谱频率处的连续谱谱级(插值)
% 由于三条线谱都在122Hz，直接在SL_dB中查找
f_line_unique = unique(f_line);
SL_cont_at_line = zeros(size(f_line));  % 各线谱位置处连续谱谱级(dB)

for k = 1:length(f_line)
    % 在校正后信号的pwelch估计中插值（已校正到目标谱级）
    SL_cont_at_line(k) = interp1(f_pw, 10*log10(Pxx_broad/p0^2), f_line(k), 'linear');
end
fprintf('\n122Hz处连续谱谱级(校正后): %.2f dB\n', SL_cont_at_line(1));

% Step 2-2: 根据SNR计算线谱功率及幅度
% 线谱SNR定义: SNR = SL_line - SL_cont
% 线谱功率谱密度: P_line_total = 10^((SL_cont + SNR)/10) * p0^2  [Pa^2/Hz]
% 但线谱是正弦信号，其功率 = A^2/2，与频率分辨率df有关:
%   在周期图中，正弦信号幅度A在频率分辨率df=1/T_frame处谱级:
%   P_periodogram(f0) = (A^2/2) * T_frame  (Pa^2/Hz 等效)
% 为使SNR在1s帧(df=1Hz)下满足要求，线谱功率密度:
%   P_line_psd = P_cont * 10^(SNR/10)   (Pa^2/Hz)
%   A^2/2 = P_line_psd * df = P_line_psd * 1   (df=1Hz时)
%   => A = sqrt(2 * P_line_psd)

x_line_total = zeros(N_total, 1);  % 所有线谱叠加

for k = 1:length(f_line)
    % 该频率处连续谱功率谱密度 (Pa^2/Hz)
    P_cont_lin = (p0^2) * 10^(SL_cont_at_line(k) / 10);

    % 线谱功率谱密度 (Pa^2/Hz)，在1Hz分辨率下满足SNR要求
    P_line_psd = P_cont_lin * 10^(SNR_line(k) / 10);

    % 正弦幅度: A^2/2 = P_line_psd * 1Hz => A = sqrt(2*P_line_psd)
    A_line = sqrt(2 * P_line_psd);

    % 生成正弦线谱（随机初相）
    phi_k   = 2 * pi * rand();
    x_line_k = A_line * sin(2*pi*f_line(k)*t + phi_k);
    x_line_total = x_line_total + x_line_k;

    fprintf('线谱%d: f=%.1fHz, SNR=%ddB, 幅度A=%.4e Pa\n', ...
        k, f_line(k), SNR_line(k), A_line);
end

% Step 2-3: 叠加宽带噪声与线谱
x_combined = x_broad + x_line_total;
fprintf('\n线谱叠加完成，信号总时长: %.1f s\n', T);

%% ==================== 周期图估计函数(内嵌) ====================
% 按公式: P(f) = (dt/N)|FFT(x)|^2，单边谱
compute_periodogram = @(seg, fs) deal( ...
    (1/fs/length(seg)) * ...
    [abs(fft(seg,length(seg))).^2 * [1; 2*ones(length(seg)/2-1,1); 1]], ...
    (0:length(seg)/2)' * (fs/length(seg)) );

function [SL_single, SL_avg, f_out] = frame_periodogram(signal, fs, frame_sec, p0)
    frame_len = round(frame_sec * fs);
    N_sig     = length(signal);
    N_frames  = floor(N_sig / frame_len);
    nfft      = frame_len;
    dt        = 1 / fs;

    P_all = zeros(nfft/2 + 1, N_frames);
    for k = 1:N_frames
        seg  = signal((k-1)*frame_len + 1 : k*frame_len);
        X    = fft(seg, nfft);
        Pk   = (dt / nfft) * abs(X).^2;
        Pone = Pk(1:nfft/2+1);
        Pone(2:end-1) = 2 * Pone(2:end-1);  % 单边谱补偿
        P_all(:, k)   = Pone;
    end

    f_out     = (0:nfft/2)' * (fs / nfft);
    SL_single = 10 * log10(P_all(:,1) / p0^2);       % 第1帧
    SL_avg    = 10 * log10(mean(P_all,2) / p0^2);    % 多帧平均
end

%% ==================== 绘图部分 ====================

%% --- 图0: 目标谱形 ---
figure('Name','目标谱形','Position',[50 700 750 380]);
semilogx(f_vec, SL_dB, 'b-', 'LineWidth',1.5);
hold on;
xline(200,  '--r', '200Hz',  'LabelVerticalAlignment','bottom');
xline(1000, '--g', '1kHz',   'LabelVerticalAlignment','bottom');
yline(144,  ':k', '144dB');
