xlabel('频率 (Hz)'); ylabel('谱级 (dB re 1μPa²/Hz)');
title('目标宽带辐射噪声谱形 (图3-1)');
grid on; xlim([1 fs/2]); ylim([80 160]);
legend('目标谱形','Location','southwest');

%% --- 图1: Task1 宽带噪声波形 ---
figure('Name','Task1 - 宽带噪声波形','Position',[50 300 1000 300]);
plot(t, x_broad, 'b', 'LineWidth', 0.3);
xlabel('时间 (s)'); ylabel('声压 (Pa)');
title('宽带辐射噪声信号波形 (Task 1)');
grid on; xlim([0 T]);

