#include <cstdlib>

class Complex {
public:
    double real, imag;
    Complex(double r = 0, double i = 0) : real(r), imag(i) {}

    friend std::istream& operator>>(std::istream& is, Complex& c);
    friend std::ostream& operator<<(std::ostream& os, const Complex& c);
};

// 去除字符串首尾空白
static std::string trim(const std::string& s) {
    size_t start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

// 尝试解析 double，返回是否成功
static bool parseDouble(const std::string& s, double& val) {
    if (s.empty()) return false;
    try {
        size_t pos;
        val = std::stod(s, &pos);
        return pos == s.size();
    } catch (...) {
        return false;
    }
}

// 解析复数字符串，返回是否成功
static bool parseComplex(const std::string& raw, Complex& c) {
    std::string s = trim(raw);
    if (s.empty()) return false;

    // ──────────────────────────────────────────────
    // 格式 (a,b) 或 (a)
    // ──────────────────────────────────────────────
    if (s.front() == '(') {
        if (s.back() != ')') return false;
        std::string inner = trim(s.substr(1, s.size() - 2));

        size_t comma = inner.find(',');
        if (comma == std::string::npos) {
            // (a) — 纯实数
            double r;
            if (!parseDouble(trim(inner), r)) return false;
            c.real = r; c.imag = 0;
            return true;
        } else {
            // (a,b)
            std::string part1 = trim(inner.substr(0, comma));
            std::string part2 = trim(inner.substr(comma + 1));
            double r, i;
            if (!parseDouble(part1, r) || !parseDouble(part2, i)) return false;
            c.real = r; c.imag = i;
            return true;
        }
    }

    // ──────────────────────────────────────────────
    // 纯虚数：以 'i' 结尾
    // ──────────────────────────────────────────────
    if (s.back() == 'i') {
        std::string body = s.substr(0, s.size() - 1); // 去掉末尾 'i'
        // body 可能是 "" / "+" / "-" / 数字 / 带符号数字
        double imag;
        if (body.empty() || body == "+") {
            imag = 1.0;
        } else if (body == "-") {
            imag = -1.0;
        } else {
            if (!parseDouble(body, imag)) return false;
        }
        c.real = 0; c.imag = imag;
        return true;
    }

    // ──────────────────────────────────────────────
    // a+bi 或 a-bi 格式
    // 需要找到虚部符号（跳过首字符，防止把开头的负号当分隔符）
    // ──────────────────────────────────────────────
    if (s.back() != 'i') {
        // 没有 i，尝试当纯实数
        double r;
        if (!parseDouble(s, r)) return false;
        c.real = r; c.imag = 0;
        return true;
    }

    return false; // 不应到达
}

// 再次尝试解析 a±bi（上面把纯实数/纯虚数已处理，这里处理混合形式）
// 重写为完整解析函数
static bool parseComplexFull(const std::string& raw, Complex& c) {
    std::string s = trim(raw);
    if (s.empty()) return false;

    // 括号格式
    if (s.front() == '(') {
        if (s.back() != ')') return false;
        std::string inner = trim(s.substr(1, s.size() - 2));
        size_t comma = inner.find(',');
        if (comma == std::string::npos) {
            double r;
            if (!parseDouble(trim(inner), r)) return false;
            c = Complex(r, 0); return true;
        }
        double r, i;
        if (!parseDouble(trim(inner.substr(0, comma)), r)) return false;
        if (!parseDouble(trim(inner.substr(comma + 1)), i)) return false;
        c = Complex(r, i); return true;
    }

    // 必须以 'i' 结尾才可能含虚部
    if (s.back() == 'i') {
        std::string body = s.substr(0, s.size() - 1); // 去掉 'i'

        // 从第二个字符起，找 '+' 或 '-'（实部与虚部的分隔）
        // 注意：从 index=1 开始搜索，跳过可能的符号前缀
        int splitPos = -1;
        for (int k = (int)body.size() - 1; k >= 1; --k) {
            if (body[k] == '+' || body[k] == '-') {
                splitPos = k;
                break;
            }
        }

        if (splitPos == -1) {
            // 纯虚数
            double imag;
            if (body.empty() || body == "+") { imag = 1.0; }
            else if (body == "-")            { imag = -1.0; }
            else if (!parseDouble(body, imag)) return false;
            c = Complex(0, imag); return true;
        }

        // 分割实部和虚部
        std::string realPart = body.substr(0, splitPos);
        std::string imagPart = body.substr(splitPos); // 含符号

        double r, i;
        if (!parseDouble(realPart, r)) return false;
        if (imagPart == "+" || imagPart.empty()) { i = 1.0; }
        else if (imagPart == "-")                { i = -1.0; }
        else if (!parseDouble(imagPart, i))      return false;

        c = Complex(r, i); return true;
    }

    // 纯实数
    double r;
    if (!parseDouble(s, r)) return false;
    c = Complex(r, 0); return true;
}

std::istream& operator>>(std::istream& is, Complex& c) {
    while (true) {
        std::string line;
        if (!std::getline(is, line)) break;
