#include <iostream>
#include <cmath>
#include <string>
using namespace std;

// ============================================================
// 1) 二维点类 Point
// ============================================================
class Point {
protected:
    double x, y;
public:
    // 有参构造函数
    Point(double x = 0.0, double y = 0.0) : x(x), y(y) {}

    // 复制构造函数
    Point(const Point& p) : x(p.x), y(p.y) {}

    // 重载复制赋值操作符
    Point& operator=(const Point& p) {
        if (this != &p) {
            x = p.x;
            y = p.y;
        }
        return *this;
    }

    double getX() const { return x; }
    double getY() const { return y; }

    // << 重载声明（类外定义）
    friend ostream& operator<<(ostream& os, const Point& p);
};

// Point 的 << 运算符类外定义
ostream& operator<<(ostream& os, const Point& p) {
    os << "(" << p.x << ", " << p.y << ")";
    return os;
}

// ============================================================
// 2) 三维点类 ThreeDPoint（公有派生自 Point）
// ============================================================
class ThreeDPoint : public Point {
protected:
    double z;
public:
    ThreeDPoint(double x = 0.0, double y = 0.0, double z = 0.0)
        : Point(x, y), z(z) {}

    ThreeDPoint(const ThreeDPoint& p) : Point(p), z(p.z) {}

    ThreeDPoint& operator=(const ThreeDPoint& p) {
        if (this != &p) {
            Point::operator=(p);
            z = p.z;
        }
        return *this;
    }

    // 设置 / 读取 z
    void setZ(double val) { z = val; }
    double getZ() const { return z; }

    // 设置所有坐标
    void setPoint(double px, double py, double pz) { x = px; y = py; z = pz; }

    // 计算与给定点的欧氏距离
    double distance(const ThreeDPoint& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        double dz = z - other.z;
        return sqrt(dx*dx + dy*dy + dz*dz);
    }

    friend ostream& operator<<(ostream& os, const ThreeDPoint& p);
};

ostream& operator<<(ostream& os, const ThreeDPoint& p) {
    os << "(" << p.x << ", " << p.y << ", " << p.z << ")";
    return os;
}

// ============================================================
// 3) 矩形类 Rectangle（保护派生自 Point）
//    左下角顶点 (x,y)，宽 width，高 height
// ============================================================
class Rectangle : protected Point {
protected:
    double width, height;
public:
    Rectangle(double x = 0.0, double y = 0.0,
              double w = 0.0, double h = 0.0)
        : Point(x, y), width(w), height(h) {}

    Rectangle(const Rectangle& r)
        : Point(r), width(r.width), height(r.height) {}

    Rectangle& operator=(const Rectangle& r) {
        if (this != &r) {
            Point::operator=(r);
            width  = r.width;
            height = r.height;
        }
        return *this;
    }

    // 设置矩形参数
    void setRectangle(double px, double py, double w, double h) {
        x = px; y = py; width = w; height = h;
    }

    // 求面积
    double area() const { return width * height; }

    // 判断任意点与矩形的关系
    // 返回 0 = 内部, 1 = 边上, 2 = 外部
    int relation(double px, double py) const {
        bool onEdge =
            ((px == x || px == x + width) && py >= y && py <= y + height) ||
            ((py == y || py == y + height) && px >= x && px <= x + width);
        if (onEdge) return 1;
        if (px > x && px < x + width && py > y && py < y + height) return 0;
        return 2;
    }

    string relationStr(double px, double py) const {
        int r = relation(px, py);
        if (r == 0) return "矩形内部";
        if (r == 1) return "矩形边上";
        return "矩形外部";
    }

    void printInfo() const {
        cout << "矩形左下角: (" << x << ", " << y << ")"
             << "  宽=" << width << "  高=" << height << endl;
    }

    double getX() const { return x; }
    double getY() const { return y; }
    double getWidth()  const { return width; }
    double getHeight() const { return height; }
};

// ============================================================
// 4) 线段类 Line（以两个 ThreeDPoint 作数据成员）
// ============================================================
class Line {
private:
    ThreeDPoint start, end;
public:
    Line(const ThreeDPoint& s, const ThreeDPoint& e) : start(s), end(e) {}

    // 显示线段信息（类外定义声明）
    void display() const;

    // 求长度（类外定义声明）
    double length() const;
};

void Line::display() const {
    cout << "线段: " << start << " --> " << end << endl;
}

double Line::length() const {
    return start.distance(end);
}

// ============================================================
// 5) 长方体类 Cuboid（私有派生自 Rectangle）
//    底面由 Rectangle 定义，高度为 depth
// ============================================================
class Cuboid : private Rectangle {
private:
    double depth;   // 长方体的"深度"（第三维高度）
public:
    Cuboid(double x = 0.0, double y = 0.0,
           double w = 0.0, double h = 0.0, double d = 0.0)
        : Rectangle(x, y, w, h), depth(d) {}

    Cuboid(const Cuboid& c) : Rectangle(c), depth(c.depth) {}

    Cuboid& operator=(const Cuboid& c) {
        if (this != &c) {
            Rectangle::operator=(c);
            depth = c.depth;
        }
        return *this;
    }

    // 表面积 = 2*(l*w + l*h + w*h)
    double surfaceArea() const {
        return 2.0 * (width * height + width * depth + height * depth);
    }

    // 体积
    double volume() const {
        return width * height * depth;
    }

    void printInfo() const {
        cout << "长方体底面左下角: (" << x << ", " << y << ")"
             << "  长=" << width << "  宽=" << height
             << "  高=" << depth << endl;
    }
};

