// ============================================================
//  student_file.cpp
//  功能：
//    1. mystring 自定义字符串类
//    2. student 类（含 << / >> 运算符重载，>>有稳健性处理）
//    3. 主函数：键盘输入6条记录 → 二进制文件
//              直接定位读取第4条 → 修改 → 回写
//              读全部记录 → 文本文件 04123122_2.txt
// ============================================================

#include <iostream>
#include <fstream>
#include <cstring>
#include <cstdlib>
#include <limits>
#include <cctype>
using namespace std;

// ============================================================
//  mystring —— 固定容量的简易字符串类（可存入二进制文件）
// ============================================================
class mystring
{
    static const int CAP = 64;   // 最大字符数（含 '\0'）
    char buf[CAP];
public:
    mystring()                  { buf[0] = '\0'; }
    mystring(const char* s)     { strncpy(buf, s, CAP - 1); buf[CAP-1] = '\0'; }
    mystring(const mystring& o) { strncpy(buf, o.buf, CAP); }

    mystring& operator=(const mystring& o)
    { if (this != &o) strncpy(buf, o.buf, CAP); return *this; }

    mystring& operator=(const char* s)
    { strncpy(buf, s, CAP - 1); buf[CAP-1] = '\0'; return *this; }

    bool operator==(const mystring& o) const { return strcmp(buf, o.buf) == 0; }
    bool operator< (const mystring& o) const { return strcmp(buf, o.buf) <  0; }
    bool operator> (const mystring& o) const { return strcmp(buf, o.buf) >  0; }

    const char* c_str() const { return buf; }
    bool empty()        const { return buf[0] == '\0'; }

    // 流运算符
    friend ostream& operator<<(ostream& os, const mystring& ms)
    { os << ms.buf; return os; }

    friend istream& operator>>(istream& is, mystring& ms)
    {
        char tmp[mystring::CAP];
        if (is >> tmp)
        {
            strncpy(ms.buf, tmp, CAP - 1);
            ms.buf[CAP - 1] = '\0';
        }
        return is;
    }
};

// ============================================================
//  student
// ============================================================
class student
{
    mystring id;       // 学号（关键字）
    mystring name;     // 姓名
    char     sex;      // 性别 M/F
    int      age;      // 年龄
    mystring address;  // 家庭地址
    float    cplus;    // C++ 成绩

public:
    // ---------- 构造函数 ----------
    student() : sex('M'), age(0), cplus(0.0f) {}

    student(mystring i, mystring n, char s, int a, mystring add, float c)
        : id(i), name(n), sex(s), age(a), address(add), cplus(c) {}

    // ---------- 比较（按学号） ----------
    bool operator<(student& e)  { return id <  e.id; }
    bool operator>(student& e)  { return id >  e.id; }
    bool operator==(student& e) { return id == e.id; }

    // ---------- 访问器 ----------
    float     Getcplus()  const { return cplus; }
    mystring  getId()     const { return id; }

    // --------------------------------------------------------
    //  operator<<  —— 文本输出（屏幕 / 文本文件通用）
    // --------------------------------------------------------
    friend ostream& operator<<(ostream& os, const student& s)
    {
        os << "学号  : " << s.id      << "\n"
           << "姓名  : " << s.name    << "\n"
           << "性别  : " << s.sex     << "\n"
           << "年龄  : " << s.age     << "\n"
           << "地址  : " << s.address << "\n"
           << "C++成绩: " << s.cplus   << "\n";
        return os;
    }

    // --------------------------------------------------------
    //  operator>>  —— 从键盘（或文本流）读取，含稳健性处理
    //
    //  稳健性措施：
    //  1. 读取后检查流状态，失败则 clear()+ignore() 并给出提示
    //  2. 性别只接受 M/F/m/f，否则重新输入
    //  3. 年龄必须为正整数（1-150），否则重新输入
    //  4. C++ 成绩必须在 [0, 100]，否则重新输入
    //  5. 学号、姓名、地址不能为空
    // --------------------------------------------------------
    friend istream& operator>>(istream& is, student& s)
    {
        // —— 学号 ——
        while (true)
        {
            cout << "  学号（无空格）: ";
            if (is >> s.id && !s.id.empty()) break;
            cout << "  [错误] 学号不能为空，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // —— 姓名 ——
        while (true)
        {
            cout << "  姓名（无空格）: ";
            if (is >> s.name && !s.name.empty()) break;
            cout << "  [错误] 姓名不能为空，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // —— 性别 ——
        while (true)
        {
            cout << "  性别（M/F）   : ";
            char c;
            if (is >> c)
            {
                c = toupper((unsigned char)c);
                if (c == 'M' || c == 'F') { s.sex = c; break; }
            }
            cout << "  [错误] 性别只能输入 M 或 F，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // —— 年龄 ——
        while (true)
        {
            cout << "  年龄（1-150） : ";
            if (is >> s.age && s.age >= 1 && s.age <= 150) break;
            cout << "  [错误] 年龄须为 1~150 之间的整数，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // —— 地址 ——
        while (true)
        {
            cout << "  地址（无空格）: ";
            if (is >> s.address && !s.address.empty()) break;
            cout << "  [错误] 地址不能为空，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // —— C++ 成绩 ——
        while (true)
        {
            cout << "  C++成绩（0-100）: ";
            if (is >> s.cplus && s.cplus >= 0.0f && s.cplus <= 100.0f) break;
            cout << "  [错误] 成绩须在 0~100 之间，请重新输入。\n";
            is.clear();
            is.ignore(numeric_limits<streamsize>::max(), '\n');
        }

        // 消耗本行剩余内容，为下一次输入做准备
        is.ignore(numeric_limits<streamsize>::max(), '\n');
        return is;
    }
};

// ============================================================
//  主函数
// ============================================================
int main()
{
    const int    N        = 6;
    const char*  BIN_FILE = "student.dat";
    const char*  TXT_FILE = "04123122_2.txt";
    const int    TARGET   = 4;   // 第 4 条（1-based）

    // ----------------------------------------------------------
    //  1. 键盘输入 N 条记录，写入二进制文件
    // ----------------------------------------------------------
    cout << "========== 输入 " << N << " 条学生信息 ==========\n";
    {
        ofstream fout(BIN_FILE, ios::binary | ios::trunc);
        if (!fout)
        {
            cerr << "[错误] 无法打开文件 " << BIN_FILE << " 进行写入。\n";
            return 1;
        }

        for (int i = 0; i < N; ++i)
        {
            cout << "\n--- 第 " << (i+1) << " 条 ---\n";
            student stu;
            cin >> stu;
            fout.write(reinterpret_cast<const char*>(&stu), sizeof(student));
            if (!fout)
            {
                cerr << "[错误] 写入第 " << (i+1) << " 条时失败。\n";
                return 1;
            }
        }
        cout << "\n已将 " << N << " 条记录写入 " << BIN_FILE << "\n";
    }

    // ----------------------------------------------------------
    //  2. 直接定位读取第 TARGET 条，显示到屏幕
    // ----------------------------------------------------------
    cout << "\n========== 读取第 " << TARGET << " 条记录 ==========\n";
    student rec4;
    {
        fstream fio(BIN_FILE, ios::binary | ios::in | ios::out);
        if (!fio)
        {
            cerr << "[错误] 无法打开文件 " << BIN_FILE << "\n";
