           << "性别  : " << s.sex     << "\n"
           << "年龄  : " << s.age     << "\n"
           << "地址  : " << s.address << "\n"
           << "C++成绩: " << s.cplus   << "\n";
        return os;
    }

    // --------------------------------------------------------
    //  operator>>  —— 从键盘（或文本流）读取，含稳健性处理
    //
    //  稳健性措施：
